css='''*{box-sizing:border-box}body{margin:0;background:#eef3f8;color:#19344f;font:16px/1.65 "Segoe UI","Microsoft YaHei",sans-serif}header{background:#133654;color:white;padding:45px max(5vw,24px)}header h1{font-size:40px;margin:0}header p{max-width:1000px}nav{position:sticky;top:0;background:white;padding:12px 5vw;box-shadow:0 2px 10px #153b5b22;z-index:2;display:flex;gap:18px;flex-wrap:wrap}a{color:#087d9c}header a{color:#8be5ef}main{max-width:1250px;margin:auto;padding:20px}section{background:white;padding:30px;margin:24px 0;border-radius:8px;border:1px solid #d7e3ed}h2{color:#123952;border-left:5px solid #00a0ae;padding-left:14px}h3{color:#126175}code,pre{font-family:Consolas,monospace;background:#edf4f8;border-radius:4px}code{padding:2px 4px}pre{padding:18px;white-space:pre-wrap;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border:1px solid #d8e3eb;padding:11px;text-align:left;vertical-align:top}th{background:#e5eef5}.scroll{overflow-x:auto}.notice{background:#fff5dd;border-left:4px solid #de9b19;padding:18px}.success{background:#e4f7ef;border-left:4px solid #178b66;padding:18px}figure{margin:24px 0}img{max-width:100%;height:auto;border:1px solid #dce6ee}figcaption{font-size:14px;color:#547087}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:15px}.card{background:#edf5f8;padding:18px;border-radius:6px}footer{padding:25px;text-align:center;font-size:14px}@media print{nav{position:static}section{break-inside:auto}h2,h3{break-after:avoid}body{background:white}header{padding:20px}a{color:#19344f}}'''

for lang in ('EN','ZH'):
    zh=lang=='ZH'
    def t(en,cn): return cn if zh else en
    parts=[]
    parts.append('<section id="manual-context-guide"><h2>'+t('0.16 · Model-aware manual meshing and persistent guidance','0.16 · 看得见模型的手动网格与常驻引导')+'</h2><p>'+t('The manual canvas shows SI geometry, domain extent and refinement references. Import boundaries explicitly, fit the model or domain, and assign editable regions. Guided steps retain the canvas; settings open inside the main-window inspector.','手动画布显示 SI 模型、流场范围和加密参考。明确导入边界、适配模型或流场，再对可编辑区域指派网格。选择引导步骤保留当前画布；设置在主窗口属性栏内打开。')+'</p><p>'+link('manual_context_guide_'+lang+'.html',t('Current usage, actual screenshots and validation','当前操作说明、实际截图与验收证据'))+'</p></section>')
    parts.append('<section id="workspace-routing"><h2>'+t('0.15 · Physics, PIMPLE, mesh/fields/export: fixed parent and summary routes','0.15 · 物理、PIMPLE、网格场导出：父项与摘要绑定修复')+'</h2><p>'+t('Single-click either the branch or summary to open persistent settings. Apply stays visible, model and PIMPLE edits generate actual dictionaries, and result actions enable after genuine data loads.','单击父项或摘要打开持久设置。应用固定可见；模型和 PIMPLE 修改生成真实字典；真实数据加载后启用结果按钮。')+'</p><p>'+link('workspace_navigation_'+lang+'.html',t('Usage, two engineer rounds and three fresh four-rank solves','用法、两轮工程验收与三组本版新四进程计算'))+'</p><div class="notice">'+t('The 0.15 evidence is linked above. Manual topology and other historical feature sections below retain their original test scope. Current_release_scope.json separates fresh and prior evidence.','0.15 本版证据见上方链接。下方手动拓扑和其他历史功能章节保留原测试范围，current_release_scope.json 区分新旧证据。')+'</div></section>')
    parts.append('<section id="manual-topology"><h2>'+t('0.14 · Manual topology: nodes, curves and regions','0.14 · 手动拓扑：节点、曲线与区域')+'</h2><p>'+t('Preprocessing → Manual topology. Draw lines and arcs, split at points, erase individual segments, and assign independent closed regions. Compiles actual blockMesh or Gmsh meshes with shared-edge constraints.','前处理 → 手动拓扑。绘制直线圆弧，点处打断、擦除单段，并对闭合区域分别指派网格，使用共享边约束编译真实 blockMesh / Gmsh 网格。')+'</p><p>'+link('manual_topology_'+lang+'.html',t('Complete manual topology instructions and fresh measured tests','完整手动拓扑说明与本版实测结果'))+'</p>'+pic('manual_topology/manual_regions_graded_'+lang+'.png',t('Native topology editor — per-region assignment','原生手动拓扑编辑器 — 分区指派'))+'</section>')
    parts.append('<section id="mesh-click-fix"><h2>'+t('0.13 · Generator and refinement: two engineer rounds','0.13 · 生成器与加密：两轮工程验收')+'</h2><p>'+t('Single-click Generator or Refinement under Mesh operations. The app switches to Preprocessing → Meshing and raises the corresponding editable property page. Heading, page tabs and feedback stay visible while the form scrolls. Apply saves the inputs; Generate/check runs the actual backend. Full settings/spacing dialogs preserve the original tools.','在网格操作下单击生成器或加密/间距，会进入前处理 → 网格，并显示对应的可编辑属性页。表单滚动时标题、页签和反馈仍可见。应用保存输入；生成/检查执行真实生成器。完整设置/间距窗口保留原工具。')+'</p><p>'+link('mesh_click_QA_'+lang+'.html',t('Two-round evidence and exact usage','两轮证据与具体用法'))+'</p>'+pic('navigation_click_QA/round2_panel_'+lang+'.png',t('Actual native current property page','当前原生属性页实图'))+'<div class="notice">'+t('Historical 0.13 evidence: that delivery reran two mouse QA iterations, three 3D pipelines per iteration, eleven regression suites, generated-file override tests and a guided solve. Older feature sections below preserve their original release evidence; in particular the eight 10-second simulations are retained from 0.12 and were not rerun in 0.14. Consult current_release_scope.json.','历史 0.13 证据：该版做了两轮鼠标验收、每轮三组三维全流程、11 项回归、生成文件覆盖检查及一组引导求解。下方历史功能章节保留原版证据；八轮 10 秒仿真来自 0.12，0.14 未重跑。详见 current_release_scope.json。')+'</div></section>')
    def section(id,title,body): parts.append(f'<section id="{id}"><h2>{title}</h2>{body}</section>')
    section('overview',t('01 · The workbench','01 · 软件概览'),
        '<p>'+t('Open Foam Friend is a working Windows desktop research application by <b>zongxuan and hanwen</b>. It connects to an explicitly configured WSL installation of OpenFOAM Foundation 14. Geometry, meshing, queued MPI solves and result export share a reproducible project and actual case files.','Open Foam Friend 是由 <b>zongxuan 和 hanwen</b> 署名的 Windows 桌面科研软件，连接用户配置的 WSL / OpenFOAM Foundation 14。几何、网格、MPI 计算队列和结果导出共享可复现的项目与真实算例文件。')+'</p>'+
        '<div class="notice">'+t('Engineering release 0.16.0. The three short 3D cylinder runs validate the software pipeline, not wake convergence, validated turbulence physics or commercial CFD certification. The current geometry editor constructs planar obstacles and extrudes them into 3D; it is not an arbitrary 3D CAD assembly editor.','工程版 0.16.0。三轮短时三维圆柱测试验证软件流程，不代表尾流已收敛、湍流物理已验证或商业 CFD 认证。当前几何编辑器绘制平面障碍物并拉伸成三维，不是任意三维 CAD 装配编辑器。')+'</div>'+pic('design.png',t('Actual Qt sketch canvas: rulers, SI dimensions, object tree and workflow properties.','真实 Qt 绘图界面：标尺、SI 尺寸、对象树与流程设置。')))
    section('install',t('02 · Installation and another computer','02 · 安装与换电脑适配'),
        '<ol><li>'+t('Keep the timestamped version folder beside <code>runtime</code>. On a new PC install 64-bit Python 3.12, Windows WSL and OpenFOAM Foundation 14 in a Linux distribution. The ZIP contains source and evidence, not a copy of your Linux distribution.','时间戳版本目录与 <code>runtime</code> 同级。新电脑先安装 64 位 Python 3.12、Windows WSL，以及 Linux 发行版中的 OpenFOAM Foundation 14。ZIP 包含源码与证据，不包含 Linux 系统镜像。')+'</li><li>'+t('Open PowerShell in the version folder and run the installer below. It creates a local Python environment and downloads the dependencies.','在版本目录打开 PowerShell，执行下方安装命令。安装器创建本地 Python 环境并下载依赖。')+'</li><li>'+t('Double-click <code>Open Foam Friend.cmd</code> at the package root, or <code>launch.cmd</code> inside the version.','双击包根目录的 <code>Open Foam Friend.cmd</code>，或版本目录中的 <code>launch.cmd</code>。')+'</li><li>'+t('Choose <b>WSL connection & CPU budget</b>. Set the distribution name, actual OpenFOAM bashrc, your Linux run directory, CPU budget and poll interval. Press OK and inspect WSL PROBE in the evidence log. Do not copy the tested host username to a different computer.','点击 <b>WSL connection & CPU budget</b>，设置发行版名称、实际 OpenFOAM bashrc、自己的 Linux 算例目录、CPU 预算与轮询间隔。确认后查看日志中的 WSL PROBE。不要把本机用户名直接照搬到其他电脑。')+'</li></ol>'+
        '<pre>powershell -NoProfile -ExecutionPolicy Bypass -File .\\install.ps1\n# Inspect Linux distribution names\nwsl --list --verbose\n# Example only: replace Ubuntu and the Linux username on another PC\nwsl -d Ubuntu -- bash -lc &quot;source /opt/openfoam14/etc/bashrc; command -v foamRun; foamRun -help&quot;</pre>'+
        table([t('Profile field','配置项'),t('Meaning','含义')],[['distro',t('Exact installed WSL distribution name, e.g. Ubuntu.','实际安装的 WSL 发行版名称，例如 Ubuntu。')],['bashrc',t('Full Linux path to Foundation 14 environment script.','Foundation 14 环境脚本的完整 Linux 路径。')],['run_dir',t('Absolute Linux path, e.g. /home/yourname/OpenFOAM/yourname14/run. The GUI opens its \\wsl.localhost path.','Linux 绝对路径，例如 /home/yourname/OpenFOAM/yourname14/run。GUI 用 \\wsl.localhost 路径打开。')],['max_cores',t('Total CPU reservation budget across this workbench queue. Paused cases keep their reservation.','本软件队列总 CPU 核心预算。暂停算例仍占用预算。')],['poll_seconds',t('Polling interval in seconds; 10 for interactive tests, 30–60 for larger jobs.','轮询秒数；交互测试可用 10，较大任务可用 30–60。')]])+
        '<p>'+t('Machine profile: <code>%APPDATA%\\OpenFoamFriend\\profile.json</code>. Projects are portable <code>*.off.json</code>; queue DB and existing case paths belong to the original host. On another PC start a fresh queue rather than copying <code>data/jobs.sqlite</code>. Windows-generated scripts use local-drive WSL /mnt paths. An actual second-PC installation has not been tested in this delivery.','机器配置：<code>%APPDATA%\\OpenFoamFriend\\profile.json</code>。<code>*.off.json</code> 项目可迁移；队列数据库与已有算例路径属于原电脑。换机使用新队列，不要复制 <code>data/jobs.sqlite</code>。Windows 脚本使用本地磁盘对应的 WSL /mnt 路径。本次尚未在另一台实体电脑上实测安装。')+'</p>')
    upgrade=json.loads((E/'upgrade_validation.json').read_text())
    section('upgrade',t('New in 0.3 · Language, mesh assistant and readable case code','0.3 升级 · 双语设置、网格助手与清晰代码界面'),
        '<p>'+t('Settings → Language / 语言 → English or 中文 switches the main interface immediately and persists the choice in <code>%APPDATA%/OpenFoamFriend/ui.json</code>. Close and reopen any existing dialog to apply the new language there. OpenFOAM dictionary keys, physical units and canonical project values remain unchanged.','设置 → Language / 语言 → English 或 中文：主界面立即切换，选择保存到 <code>%APPDATA%/OpenFoamFriend/ui.json</code>。已经打开的对话框关闭后重新打开即可切换。OpenFOAM 字典关键字、物理单位与项目内部规范值保持一致。')+'</p>'+pic('workspace_ZH.png',t('Actual upgraded Chinese workspace.','升级后真实中文工作界面。'))+
        '<h3>'+t('A guided automatic mesh workflow','分阶段自动网格流程')+'</h3><ol><li>'+t('Draw the geometry, then choose Auto mesh assistant. Confirm 2D/3D and the method: a single circle recommends a cylinder O-grid; general planar obstacles recommend Gmsh triangles/prisms; an empty box can use conformal partitioned blocks.','绘制几何后点击自动网格助手。确认二维/三维与方法：单个圆推荐圆柱 O-grid；一般平面障碍物推荐 Gmsh 三角形/棱柱；无障碍矩形流场可用共形分块。')+'</li><li>'+t('Choose Quick preview, Balanced or Fine, then adjust actual counts and sizes. O-grid cell count is Nr × Nθ × Nz (Nz=1 for 2D); presets are 5120, 20480 and 81920 in four-layer 3D. The displayed estimate for Gmsh is intentionally not an exact cell count.','选择快速预览、均衡或精细预设，再调整实际数量与尺寸。O-grid 单元数为 Nr × Nθ × Nz（二维 Nz=1）；四层三维预设为 5120、20480、81920。Gmsh 生成前不能给出精确单元数。')+'</li><li>'+t('For Gmsh, optional near-body and downstream wake rectangles provide smoothly blended size fields. The assistant clips them to the rectangular domain and retains manual regions. The wake direction is x+; ratio controls end/start target size. For O-grid these local controls are disabled: that method supports radial grading, not a Cartesian wake strip.','Gmsh 可选近体与下游尾流矩形，提供平滑过渡的尺寸场。助手裁剪到矩形流场内并保留手动区域。尾流方向为 x+，ratio 为终点/起点目标尺寸比。O-grid 禁用这些局部选项，因为该方法只支持径向渐变，不生成笛卡尔尾流条带。')+'</li><li>'+t('Set explicit skewness and non-orthogonality limits. Generate and check real preview creates a unique mesh-only WSL case, runs the converter and checkMesh, then opens the real mesh. A failed quality gate stays failed; thresholds are never relaxed automatically. Apply settings only saves design settings without generating a case.','明确设置 skewness 和非正交角门槛。生成并检查真实预览会创建唯一 WSL 网格算例，执行转换及 checkMesh，并自动显示真实网格。质量不达标时保持失败，不自动放宽门槛。仅应用设置只修改设计，不生成算例。')+'</li></ol>'+pic('mesh_assistant_'+lang+'.png',t('Actual staged automatic mesh assistant.','真实分阶段自动网格助手。'))+pic('guided_mesh_preview.png',t('Generated 5120-cell O-grid, shown as a real quadrilateral mid-slice.','已生成的 5120 单元 O-grid，展示真实四边形中截面。'))+
        '<h3>'+t('More precise drawing controls','更精确的绘图控制')+'</h3><p>'+t('Precise shape creates circle/rectangle/triangle objects with numeric SI dimensions. Double-click a canvas object to edit it. Sketch settings selects ruler units m/cm/mm and snap spacing in metres (0 disables snapping). These settings only change the displayed ruler and snapping, not the physical project units. Select supports a selection box; Ctrl+Z undo, Ctrl+Y redo, Ctrl+D duplicate, Delete removes selected objects, Esc returns to selection. Right-click offers edit/duplicate/delete. Measure provides a live segment preview.','精确绘制支持圆、矩形、三角形的 SI 数值尺寸输入。双击画布对象可编辑。绘图设置选择标尺 m/cm/mm 和以米计的吸附间距（0 关闭吸附）；标尺显示单位不改变项目物理单位。选择工具支持框选；Ctrl+Z 撤销、Ctrl+Y 重做、Ctrl+D 复制、Delete 删除选中对象、Esc 返回选择。右键支持编辑/复制/删除，测量工具显示实时线段。')+'</p>'+
        '<h3>'+t('A readable editor for the actual dictionaries','真实字典的清晰编辑界面')+'</h3><p>'+t('Actual dictionaries opens a grouped system/constant/0 file tree, line-numbered non-wrapping code with syntax colours, search, token-preserving indentation and a parameter reference panel. Format changes whitespace while asserting the exact token sequence is retained. Structure check only validates balanced delimiters and the FoamFile header; it is not a complete OpenFOAM parser. Save current file rechecks that the case is DONE/FAILED/CANCELLED, writes a timestamped backup, then atomically replaces that file. Queued and active cases stay read-only.','真实字典界面提供 system/constant/0 分组文件树、行号、不自动折行的代码、语法颜色、搜索、保持 token 的缩进格式化与参数说明。格式化只改变空白，并检查 token 序列完全一致。结构检查仅核验括号配对与 FoamFile 头，不等于完整 OpenFOAM 解析。保存当前文件会重新检查算例处于 DONE/FAILED/CANCELLED，写时间戳备份后原子替换；排队与运行中的算例只读。')+'</p>'+pic('dictionary_editor_'+lang+'.png',t('Actual reformatted fvSolution, file tree and parameter reference.','真实格式化 fvSolution、文件树与参数说明。'))+
        '<p>'+t('Polling now batches live status inside Linux rather than reading hot solver/state files through Windows UNC. Completed-job log summaries are cached. The actual dictionaries and results remain in the WSL case folder. Help → Website support opens ','轮询改为在 Linux 内批量读取实时状态，避免通过 Windows UNC 反复读取求解中的热文件。已完成任务的日志摘要缓存；真实字典与结果仍保存在 WSL 算例目录。帮助 → 网站支持打开 ')+link('http://spaceaero.space','spaceaero.space')+'.</p>'+
        table([t('Upgrade check','升级检查'),t('Measured result','实测结果')],[
            [t('Runtime Chinese/English switch','运行时中英切换'),'PASS'],[t('Canonical values retained','规范参数值保留'),'PASS'],[t('Draw, undo, redo, duplicate, delete','绘制、撤销、重做、复制、删除'),'PASS'],
            [t('Formatted fvSolution read by actual foamDictionary','真实 foamDictionary 读取格式化 fvSolution'),'PIMPLE/nOuterCorrectors = '+upgrade['openfoam_parser_after_formatted_save']],
            [t('Guided O-grid preview','助手 O-grid 预览'),str(upgrade['real_previews']['ogrid_preview']['cells'])+' cells · DONE'],
            [t('Assisted Gmsh near/wake mesh','助手 Gmsh 近体/尾流网格'),str(upgrade['real_previews']['unstructured_preview']['cells'])+' cells · max skew '+str(round(upgrade['real_previews']['unstructured_preview']['skewness'],6))+' · max angle '+str(round(upgrade['real_previews']['unstructured_preview']['nonorthogonality'],6))+'° · limits 0.5 / 30° · DONE']])+
        '<p>'+link('../evidence/upgrade_validation.json',t('Raw upgrade test evidence','升级测试原始证据'))+'</p>')
    workbench=json.loads((E/'workbench_validation.json').read_text())
    section('workbench',t('0.3 · Contextual workspaces and optional guided simulation','0.3 · 专业工作区与可选引导式仿真'),
        '<p>'+t('The previous global sketch toolbar appeared over every page because it belonged to the main window. This release uses context: Geometry exposes sketch/edit/mesh preparation; Scenes exposes fit/quality/image controls and the real VTK field/time controls; Run Queue exposes refresh, connection and case-code controls. Drawing actions are hidden and disabled outside Geometry. The inspector follows the same context; exports are enabled only for a loaded Scene.','上一版绘图工具栏属于主窗口，所以每个页面都显示。本版按上下文切换：几何显示绘图、编辑及网格准备；场景显示视图、质量、图像导出及真实 VTK 场/时间控制；队列显示刷新、连接与算例代码。几何以外的页面隐藏并禁用绘图操作，右侧面板同样按工作区切换；加载真实场景后才启用导出。')+'</p>'+pic('context_page_2_EN.png',t('Actual Run Queue workspace: no sketch toolbar or drawing controls.','真实队列工作区：不显示绘图工具栏或绘图控制。'))+
        '<p>'+t('The current Simulation Tree has Geometry / solid obstacles, one Mesh operations branch containing backend and refinement controls, Construction curves, Physics continuum, Solver / stopping criteria and Scenes / reports. Double-click objects for dimensions, the physics branch for solver settings, and other branches to navigate. New/open project returns to Geometry. The underlying solver is still OpenFOAM, not STAR-CCM+.','当前仿真树包含几何/实体、唯一网格操作分支（后端与加密区域）、辅助线、物理连续体、求解器/停止条件、场景/报告。双击对象编辑尺寸，双击物理分支打开求解设置，其他分支用于工作区导航。新建或打开项目回到几何。底层求解器仍为 OpenFOAM。')+'</p>'+
        '<h3>'+t('Enable or disable the guide','开启或关闭引导')+'</h3><p>'+t('Settings → Guided workflow shows or hides the optional guide; the choice is saved alongside the language preference. Expert mode is the same application with the guide hidden. The guide is a dock, not a blocking wizard: other workspaces remain accessible. Close its dock or uncheck the menu to return to expert mode. Reset workspace layout restores dock positions without replacing the project.','设置 → 引导式流程，显示或隐藏可选引导；选择与语言设置一起保存。隐藏引导就是专家模式。引导为停靠面板，不是锁住窗口的向导，可以继续访问其他工作区。关闭引导面板或取消菜单勾选即可回到专家模式。重置界面布局恢复面板位置，不替换项目。')+'</p>'+pic('guided_geometry_ZH.png',t('Actual optional guide and simulation tree; Chinese is selected in this screenshot.','真实可选引导面板与仿真树，本截图选择中文。'))+
        table([t('Step','步骤'),t('Action','操作'),t('What qualifies as ready','核验依据')],[
        ['01',t('WSL connection','WSL 连接'),t('A genuine successful executable probe for the current distro/bashrc/run directory.','对当前发行版、环境脚本、算例目录实际执行可执行程序核验。')],
        ['02',t('Geometry review','几何核验'),t('Explicit input review; domain/shape validation. A change to geometry invalidates the review.','主动核验流场与实体输入。几何修改后该核验失效。')],
        ['03',t('Mesh and quality','网格与质量'),t('Latest matching mesh settings in an actual DONE case, with checkMesh passed. Failed or in-progress meshes cannot qualify.','最新参数匹配的真实算例处于 DONE，且 checkMesh 通过；失败或仍在运行的网格不算通过。')],
        ['04',t('Physics and time','物理与时间'),t('Explicit validation of the current flow/time/output/core inputs. Changing these settings invalidates the review.','主动核验当前流动、时间、输出与核心参数；修改后需重新核验。')],
        ['05',t('Submission / monitor','提交 / 监控'),t('Guide submission stays disabled until steps 01–04 are ready. The button submits a real design snapshot; if a matching solve exists, it opens that case instead.','引导提交在前四步核验前禁用。按钮提交真实设计快照；已有匹配求解时显示该任务。')],
        ['06',t('Result / export','结果 / 导出'),t('Matching non-mesh-only case is DONE and the measured simulation time reaches its requested end. Open actual fields, then select exports.','参数匹配的求解算例完成且实际时间达到设定终点；打开真实场后选择导出。')]])+
        '<p>'+t('Matching uses SHA-256 of canonical project inputs, not file names. Mesh matching includes geometry, regions, topology, resolutions, smoothing and quality limits; solver matching also includes flow and time settings. A velocity/viscosity change retains applicable mesh evidence but invalidates the physics review and solution match. Renaming a case does not change its physics. Reviews are session-specific; switching the guide off and on in that session retains them. This gate belongs to the guide; expert queue controls remain available. Input review and short DONE cases are not physical-convergence claims.','证据匹配使用规范项目输入的 SHA-256，而非文件名。网格匹配包含几何、区域、拓扑、分辨率、平滑与质量阈值；求解匹配还包含流动及时间设置。修改速度/黏度可保留适用网格证据，但物理核验和解匹配失效。重命名不改变物理条件。输入核验在本次会话内有效；隐藏后重新开启引导仍保留。本门槛属于引导流程，专家队列控制仍可使用。输入核验与短时 DONE 算例不等于物理收敛。')+'</p>'+pic('guided_results_'+lang+'.png',t('Native guide controls showing the actual completed case.','原生引导控件展示真实已完成算例。'))+pic('guided_field.png',t('Pressure at the genuine final saved time of the guided case; captured directly from VTK, separately from the native controls.','引导算例真实末保存时刻的压力场；直接从 VTK 捕获，与原生控件分别展示。'))+
        '<p>'+t('The real guided test submitted a new 5120-cell, four-core case to ','真实引导测试提交了新的 5120 单元、四核算例，推进至 ')+str(workbench['guided_real_case']['end_time_s'])+' s · '+str(workbench['guided_real_case']['saved_frames'])+t(' saved frames. Context visibility, blocked submission, stale-evidence invalidation and the persisted optional mode all passed.',' 个保存帧。工作区工具切换、未核验提交拦截、旧证据失效及可选模式保存均通过。')+'</p>'+link('../evidence/workbench_validation.json',t('Raw workbench validation','工作区测试原始证据'))+
        '<p>'+t('Design basis: Siemens describes a simulation tree and pipelined mesh operations. This workbench applies those workflow principles with its own Qt/OpenFOAM implementation.','设计依据：Siemens 描述仿真树与网格操作流水线；本软件以自己的 Qt/OpenFOAM 实现采用这些流程原则。')+' '+link('https://blogs.sw.siemens.com/simcenter/simcenter-star-ccm-2019-1-handling-complex-assemblies-just-got-easier/','Siemens: Simulation Tree & meshing pipeline')+'.</p>')
    section('sketch',t('03 · Dimensioned geometry and control regions','03 · 尺寸化几何与网格控制区域'),
        '<ol><li>'+t('Start with Cylinder preset or open a project. Set domain dimension, rectangular bounds and extrusion depth. All values are SI: metres, seconds, m/s and m²/s. For an O-grid the actual outer boundary is a circle of <code>outer_radius</code>; rectangular xmin/xmax do not define that topology.','从 Cylinder preset 或已有项目开始，设置维度、矩形流场边界和拉伸厚度。所有参数使用 SI：米、秒、m/s 与 m²/s。O-grid 的实际外边界是 <code>outer_radius</code> 指定的圆，不由矩形 xmin/xmax 定义。')+'</li><li>'+t('Choose Circle, Rectangle or Triangle and drag a bounding box. Select and move objects; double-click their tree entries for exact centre and size. Circle width is diameter; equal width/height is required by the cylinder O-grid. Eraser deletes an object; Undo restores the previous sketch.','选择 Circle、Rectangle 或 Triangle，拖动外包框绘制。Select 可移动对象，双击对象树条目设置精确中心与尺寸。圆的 width 是直径；圆柱 O-grid 要求 width 与 height 相等。Eraser 删除对象，Undo 撤销绘图操作。')+'</li><li>'+t('Wheel zooms the sketch; Pan drags the view; Fit fits the domain. Pointer coordinates use metres; Sketch settings selects ruler units m/cm/mm and snap spacing (0 disables snapping). Precise shape and numerical dimensions support small geometries. Measure reports distance.','滚轮缩放，Pan 拖动视图，Fit 适配流场。鼠标坐标使用米；绘图设置可选择标尺 m/cm/mm 与吸附间距（0 关闭吸附）。微小模型可用精确绘制与数值尺寸。测量工具显示距离。')+'</li><li>'+t('Draw Mesh region rectangles and edit x/y/width/height, size, direction and ratio. A mesh region is a control object, not a solid obstacle. Choose the supported method below before generation.','绘制 Mesh region 矩形，编辑 x/y/width/height、size、direction 与 ratio。网格区域是控制对象，不是实体障碍物。生成前先选择下方受支持的方法。')+'</li><li>'+t('Save project before submission. A unique safe case name prevents overwriting existing results. Changing the sketch after submitting does not change that queued case snapshot.','提交前保存项目。使用唯一、合法的算例名称，避免覆盖结果。提交后修改画布不会改变已排队算例的参数快照。')+'</li></ol>')
    methods=[
        ['Structured cylinder O-grid',t('Conformal quadrilateral cross-section / hexahedral volume','共形四边形截面 / 六面体体网格'),t('Exactly one circle; radial, circumferential and spanwise counts; radial simpleGrading. Rectangular control regions are not used by this method.','仅支持一个圆；径向、圆周、展向单元数与径向 simpleGrading；此方法不使用矩形网格区域。')],
        ['Structured partitioned box',t('Manual shared block partitions / hexahedra','手动共享块分区 / 六面体'),t('Empty rectangular flow box; erase all obstacles first. Region edges become shared x/y partition lines. Counts and grading propagate along shared axes for conformal interfaces.','无障碍物矩形流场，需先删除实体；区域边界生成共享 x/y 分区线；沿共享轴传播划分数与渐变，保持接口共形。')],
        ['Gmsh triangle / prism',t('Automatic triangles extruded to prisms','自动三角形拉伸成棱柱'),t('Circle/rectangle/triangle obstacles and smooth region size fields. In 2D, one empty layer; in 3D, specified spanwise layers.','支持圆、矩形、三角形障碍物与平滑区域尺寸场；二维一层 empty，三维按展向层数拉伸。')],
        ['Gmsh quadrilateral / prism',t('Automatic quad-dominant mixed hex/prism','自动四边形为主的六面体/棱柱混合网格'),t('Recombination does not guarantee an all-quad mesh. Inspect the actual converted mesh and quality.','重组不保证全四边形；必须检查转换后实际网格与质量。')],
        ['Gmsh tetrahedral',t('Automatic 3D tetrahedra','自动三维四面体'),t('Extruded volume geometry; HXT algorithm and Netgen optimization; no 2D tetrahedra.','拉伸体几何，HXT 算法与 Netgen 优化；不支持二维四面体。')],
    ]
    section('mesh',t('04 · Mesh methods and directional grading','04 · 网格方法与方向渐变'),table([t('Method','方法'),t('Cells','单元'),t('Controls / scope','控制 / 范围')],methods)+
        '<h3>'+t('Uniform and increasing / decreasing size','均匀与增大 / 减小尺寸')+'</h3><p>'+t('For manual blocks, <code>ratio</code> is last-cell width / first-cell width in the selected positive axis; negative directions invert it. Uniform means ratio 1. For N cells and expansion E, adjacent growth g = E^(1/(N−1)); first width is L(g−1)/(g^N−1), or L/N at E=1. This is not a per-cell factor E.','手动块的 <code>ratio</code> 是沿所选正轴的末单元宽度 / 首单元宽度；负方向取倒数。均匀对应比值 1。N 个单元、总膨胀比 E 时，相邻增长率 g = E^(1/(N−1))，首层宽度为 L(g−1)/(g^N−1)，E=1 时为 L/N。E 不是相邻两格的增长率。')+'</p>'+
        '<pre>blockMesh: hex (...) (Nr Ntheta Nz) simpleGrading (E 1 1)\nGmsh x+ size target: h(x) = h0 × ratio^((x − x0)/width)\nGmsh x−: use the inverse exponential; y directions are analogous.\nSmooth transition: h = h_background + W(x,y) × (h_target − h_background)\nW: product of four tanh edge weights; overlapping fields use Min.</pre>'+
        '<p>'+t('Gmsh regions specify target sizes, not exact final element widths. The tanh blend reduces abrupt size transitions; smoothing iterations and curvature resolution complement it. They do not guarantee acceptable skewness: the OpenFOAM gate remains mandatory. For a high-quality cylinder baseline, prefer the structured O-grid and moderate adjacent growth. Six-faced <b>hexahedra</b> are supported; arbitrary 2D hexagonal polygon tilings are not implemented.','Gmsh 区域指定目标尺寸，不保证生成单元宽度严格相等。tanh 混合减缓尺寸突变，平滑迭代与曲率分辨率辅助改善质量，但不保证 skewness 合格，必须通过 OpenFOAM 检查。高质量圆柱基准优先使用结构 O-grid 与温和相邻增长。支持六个面的<b>六面体</b>，尚未实现任意二维六边形多边形铺网格。')+'</p>'+
        '<p>'+t('Use <b>Generate / check mesh only</b> before an expensive solve. Select the resulting queue row and <b>Open result</b> to view the real mesh. A .foam file is a marker pointing to the complete case directory, not a self-contained mesh file.','昂贵计算前先使用 <b>Generate / check mesh only</b>。选择生成后的队列行，点击 <b>Open result</b> 查看真实网格。.foam 是完整算例目录的入口标记，不是独立网格文件。')+'</p>')
    section('quality',t('05 · Quality, bad faces and singular cells','05 · 质量、坏面与奇异单元'),
        '<p>'+t('Every submitted mesh runs <code>checkMesh -allGeometry -allTopology</code> with the project’s explicit skew and non-orthogonality thresholds. The solve is blocked unless its log contains Mesh OK. Default project limits are skewness 0.5 and non-orthogonality 30°. These are chosen gates, not universal accuracy criteria. Quality above a threshold is counted by <b>face</b>, not silently relabelled as cell count.','每个提交网格执行 <code>checkMesh -allGeometry -allTopology</code>，使用项目明确设定的 skewness 与非正交角阈值。日志没有 Mesh OK 就阻止求解。项目默认门槛为 skewness 0.5、非正交角 30°，是本软件选择的门槛，不是通用精度标准。超阈值数量按<b>面</b>统计，不能当作单元个数。')+'</p>'+
        table([t('Metric','指标'),t('Definition / provenance','定义 / 来源')],[
        ['Non-orthogonality',t('Internal face angle α=acos((Sf·d)/(|Sf||d|)); d=neighbour centre−owner centre. 0° is orthogonal.','内部面的 α=acos((Sf·d)/(|Sf||d|))；d 为邻居中心减 owner 中心；0° 为正交。')],
        ['OpenFOAM face skewness',t('Offset sv=Cpf−d(Sf·Cpf)/(Sf·d), normalized by max(0.2|d|, maximum point projection along sv). Boundary faces use normal projection and factor 0.4. Uses Foundation14 meshCheck formulas; it is not the triangle-angle skewness diagram metric.','偏移 sv=Cpf−d(Sf·Cpf)/(Sf·d)，以 max(0.2|d|，顶点沿 sv 方向最大投影距离) 归一化；边界面使用法向投影与系数 0.4。采用 Foundation14 meshCheck 公式，与三角形角度 skewness 图示指标不同。')],
        ['Aspect ratio / AR',t('Reported directly from checkMesh; it describes cell stretching and is not used as a replacement for skewness or orthogonality.','直接读取 checkMesh，描述单元拉伸；不能替代 skewness 或正交性。')],
        [t('Singularity indicators','奇异指标'),t('Independent signed-volume count/minimum plus OpenFOAM topology, determinant, concavity and geometry checks. Red markers show the worst face location, not every possible mathematical singularity.','独立有符号体积的最小值与非正数量，以及 OpenFOAM 拓扑、行列式、凹性与几何检查。红色标记显示最坏面位置，不等于穷尽所有数学奇异点。')],
        ])+'<p>'+t('Select a case in Run Queue, then click Locate worst skewness / non-orthogonality. The viewer draws the actual faces, colours their calculated metric and places a red marker at the worst face centre. IDs, XYZ coordinates and threshold counts appear in the log and <code>off_quality.json</code>. Calculation uses the actual ASCII polyMesh, including volume-weighted cell centres. Binary imported meshes need conversion to ASCII for this independent audit.','在 Run Queue 选择算例，点击 Locate worst skewness / non-orthogonality。视图绘制实际面，以计算指标着色，并在最坏面中心放置红色标记。ID、XYZ 与超阈值数量输出到日志和 <code>off_quality.json</code>。计算读取实际 ASCII polyMesh，使用体积加权单元中心。二进制导入网格需转成 ASCII 才能使用此独立审计。')+'</p>'+pic('quality.png',t('Independent per-face quality rendering; the marker identifies the actual worst face.','独立逐面质量显示，标记指向实际最坏面。')))
    params=[['Re','U∞D/ν','200'],['D / U∞ / ν','m / m·s⁻¹ / m²·s⁻¹','1 / 1 / 0.005'],['Nr × Nθ × Nz',t('True 3D cell count','真实三维单元数'),'20 × 64 × 4 = 5120'],['Outer radius / depth','m','10 / 1'],['Radial expansion E',t('Last / first width','末格 / 首格宽度'),'20'],['Turbulence',t('Model selection','模型选择'),'laminar'],['Solver',t('Foundation14 transient incompressible','Foundation14 瞬态不可压'),'foamRun -solver incompressibleFluid'],['PIMPLE','nOuterCorrectors / nCorrectors / nNonOrthogonalCorrectors','2 / 2 / 1'],['Time integration / convection',t('Actual fvSchemes','实际 fvSchemes'),'Euler / linearUpwind grad(U)'],['maxCo / maxDeltaT','— / s','0.3 / 0.0005'],['p tolerance / relTol','—','1e−8 / 0.01; pFinal relTol 0'],['U tolerance / relTol','—','1e−9 / 0.1; UFinal relTol 0']]
    section('solver',t('06 · Physics, case code and boundary conditions','06 · 物理设置、算例代码与边界条件'),table([t('Parameter','参数'),t('Meaning / unit','含义 / 单位'),t('Validation value','验证值')],params)+
        '<p>'+t('Flow & solver settings controls U, viscosity, 24 laminar / RAS / LES / hybrid options, duration, maximum internal timestep, saved-field interval, Co and requested cores. Output interval is not the solver timestep. U,p initial fields, physicalProperties, momentumTransport, controlDict, fvSchemes, fvSolution and decomposeParDict are written to the real Linux case. View / edit case dictionaries exposes them; edit inactive cases only.','Flow & solver settings 设置速度、运动黏度、24 laminar / RAS / LES / hybrid options、模拟时长、最大内部时间步、场保存间隔、Co 和核心数。输出间隔不等于求解步长。U,p 初始场、physicalProperties、momentumTransport、controlDict、fvSchemes、fvSolution、decomposeParDict 都写入真实 Linux 算例。View / edit case dictionaries 可查看并修改，限定非运行状态。')+'</p>'+
        table([t('Boundary','边界'),'U','p'],[['inlet','fixedValue (U∞,0,0)','zeroGradient'],['outlet','zeroGradient','fixedValue 0'],['cylinder','noSlip','zeroGradient'],['farfield','fixedValue (U∞,0,0)','zeroGradient'],['front / back, 2D','empty','empty'],['front / back, 3D','symmetryPlane','symmetryPlane']])+
        '<p>'+t('The O-grid has no farfield patch: the upstream semicircle is inlet and downstream semicircle outlet. Gmsh rectangular domains have inlet, outlet and lateral farfield. The validation mesh is geometrically 3D with four z layers, but spanwise-invariant initial/boundary conditions may retain spanwise-invariant flow. It is not a resolved 3D transition or LES benchmark.','O-grid 没有 farfield patch：上游半圆为入口，下游半圆为出口。Gmsh 矩形域具有入口、出口和侧面 farfield。验证网格几何上为三维，有四层 z 单元，但展向不变的初始/边界条件可能维持展向不变流动，不是充分解析三维转捩或 LES 基准。')+'</p>'+
        '<p>'+t('kOmegaSST initialization uses k=1.5(U∞I)² and ω=√k/(0.09^¼L), with kqRWallFunction / omegaWallFunction / nutkWallFunction. Wall resolution and y+ suitability require separate physical validation; this release does not automatically optimize y+ or promise a correct high-Re wall treatment. Pressure p has units m²/s²; physical pressure requires density.','kOmegaSST 初始化采用 k=1.5(U∞I)²、ω=√k/(0.09^¼L)，配置 kqRWallFunction / omegaWallFunction / nutkWallFunction。壁面分辨率与 y+ 适用性需单独验证，本版不自动优化 y+，不保证高雷诺数壁面处理正确。压力 p 单位为 m²/s²；换为物理压力须乘密度。')+'</p>')
    section('queue',t('07 · Queue, parallel jobs and restart','07 · 队列、并行任务与恢复'),
        '<p>'+t('Submit snapshots the project. The durable SQLite queue claims CPU reservations transactionally. Jobs can run simultaneously when their summed requested cores fit the budget; four-core jobs under a budget of four run sequentially. A scheduler lock prevents GUI and headless worker from launching the same job twice. Each case records stage files, logs and verified MPI process IDs.','Submit 固化项目快照。SQLite 持久队列通过事务领取 CPU 预算，核心总数不超过预算时可并发；预算为 4 时，多个 4 核任务顺序运行。调度文件锁防止 GUI 与后台调度器重复启动任务。每个算例记录阶段、日志和经验证的 MPI 进程 ID。')+'</p>'+
        '<pre>QUEUED → STARTING → MESHING → CHECKING → RUNNING → EXPORTING → DONE\n                         quality failure / solver failure → FAILED\nRUNNING ↔ PAUSED; lost heartbeat → STALLED; explicit cancellation → CANCELLED</pre>'+
        '<ul><li>'+t('Select a row to see actual logs, residuals, max observed Co and checkMesh metrics. ETA extrapolates recent simulated-time progress; it is an estimate and changes with solver speed.','选择行查看真实日志、残差、监测到的最大 Co 与 checkMesh 指标。ETA 根据已推进模拟时间估算，会随计算速度改变。')+'</li><li>'+t('Earlier / Later reorders queued jobs. Pause sends STOP only to the verified case MPI launcher and descendants; Continue sends CONT. Pause does not erase or rewrite fields.','Earlier / Later 调整待运行顺序。Pause 仅对已核验的该算例 MPI 主进程及子进程发送 STOP，Continue 发送 CONT；暂停不删除或改写场。')+'</li><li>'+t('Cancel supports queued or running/paused solver cases. Meshing/checking/export cannot currently be cancelled from the GUI. A paused job keeps its CPU reservation.','Cancel 支持待运行、运行或暂停求解算例；当前 GUI 不支持取消正在生成网格、检查或导出的阶段。暂停任务仍保留 CPU 预算。')+'</li><li>'+t('Closing the GUI leaves running detached WSL drivers alive and starts a hidden headless scheduler if work is queued. Reboot terminates solvers; pause is not persistent process suspension across a reboot.','关闭 GUI 后，已运行的独立 WSL 驱动继续；有待运行任务时启动隐藏后台调度器。重启会终止求解器，暂停不能跨重启保持进程。')+'</li><li>'+t('After reboot reopen the same version. Inspect logs and choose Recover checkpoint for FAILED / STALLED. Recovery requires no live old MPI process, enough CPU budget, and matching complete U,p saved times in every processor. It resumes latestTime without remeshing. Recovery after solver completion but export failure requires manual reconstruction/export.','重启后打开同一版本，检查日志，选择 FAILED / STALLED 算例并点击 Recover checkpoint。要求旧 MPI 已退出、CPU 预算足够、所有 processor 的完整 U,p 最新时间一致。恢复从 latestTime 开始，不重新划网格。求解已结束但导出失败时需手动重建/导出。')+'</li></ul>'+pic('queue.png',t('The three completed validation cases in the actual GUI queue.','真实 GUI 队列中的三轮已完成测试。')))
    section('post',t('08 · VTK viewing, animation and PINN exports','08 · VTK 查看、动画与 PINN 导出'),
        '<p>'+t('Open result loads the genuine reconstructed .foam case with vtkOpenFOAMReader. Select Mesh, p, U or other available cell arrays; U uses vector magnitude colouring. Toggle Edges; choose Full volume or XY/XZ/YZ mid-slice. Wheel zooms, left drag rotates, middle drag pans; Fit resets the camera. Clicking reports a displayed cell ID and XYZ. The slice cutter preserves quadrilateral polygons when present; existing triangular cells remain triangles. Rendering does not alter the OpenFOAM mesh.','Open result 用 vtkOpenFOAMReader 读取真实重建后的 .foam 算例。选择 Mesh、p、U 或其他单元场；U 按矢量模着色。Edges 控制边线，选择全体积或 XY/XZ/YZ 中截面。滚轮缩放，左键拖动旋转，中键平移，Fit 重设相机。点击报告显示单元 ID 与 XYZ。切片保留已有四边形多边形，原始三角形单元仍显示三角形；渲染不改变 OpenFOAM 网格。')+'</p>'+pic('round3_pressure.png',t('Actual final pressure slice from round 3; p is kinematic pressure.','第三轮真实末时刻压力切片，p 为运动学压力。'))+
        '<ul><li>'+t('PNG exports the rendered VTK view. GIF visits the actual saved CFD times; playback uses 150 ms per image and is not physical-time playback. It does not synthesize intermediate CFD frames.','PNG 导出 VTK 渲染视图；GIF 遍历真实保存的 CFD 时间，每帧播放 150 ms，不等于物理时间播放，也不合成中间 CFD 帧。')+'</li><li>'+t('CSV: enter comma-separated column names (x,y,z,t,U_x,U_y,U_z,U_mag,p), choose current/all times and positive row stride. Coordinates are cell-centre samples. This is a row-stride selector, not an arbitrary spatial query/filter engine.','CSV：输入逗号分隔列名 (x,y,z,t,U_x,U_y,U_z,U_mag,p)，选择当前/全部时间和正整数行间隔。坐标为单元中心采样；当前是间隔选行，不是任意空间查询/过滤引擎。')+'</li><li>'+t('MAT contains xytuvp (Nrows,6), full xyztuvwp (Nrows,8), actual time_values_s, column names, units and z_planes. Rows are time-major, then cell order. For a 3D PINN use xyztuvwp; xytuvp drops each row’s z and w and is insufficient to define a full 3D learning problem. No implicit nondimensionalization is applied.','MAT 包含 xytuvp (Nrows,6)、完整 xyztuvwp (Nrows,8)、真实 time_values_s、列名、单位和 z_planes。按时间优先、再按单元排列。三维 PINN 应读取 xyztuvwp；xytuvp 丢失每行 z、w，不足以定义完整三维学习问题。不暗中无量纲化。')+'</li></ul>'+
        '<pre>from scipy.io import loadmat\na = loadmat("round3.mat")\nfull = a["xyztuvwp"]  # columns: x,y,z,t,u,v,w,p\ntime = a["time_values_s"].ravel()\n# A 2D model may use xytuvp only after explicitly selecting a z plane.</pre>'+
        '<p>'+t('Large full-field MAT/GIF exports build arrays in memory. For large production runs, use smaller saved-field sets or CSV stride; streaming HDF5/VTU exports are a future extension.','大规模全场 MAT/GIF 在内存中组合数组。正式大算例需减少保存场或使用 CSV 行间隔；流式 HDF5/VTU 导出尚待扩展。')+'</p>')
    section('fft',t('09 · Actual force FFT and Strouhal definition','09 · 真实力系数 FFT 与 Strouhal 定义'),
        '<p>'+t('Postprocess → Force history & single-sided FFT reads genuine OpenFOAM forceCoeffs data and displays Cd/Cl history with the lift amplitude spectrum. There is no Hann window, smoothing, filtering, zero padding or mean removal. The DC bin is retained; the annotated peak is the largest non-DC bin, not automatically a validated shedding fundamental.','Postprocess → Force history & single-sided FFT 读取真实 OpenFOAM forceCoeffs，显示 Cd/Cl 历史与升力振幅谱。不加 Hann 窗，不平滑、不滤波、不补零、不去均值；保留 DC。标出的峰为最大非 DC bin，不自动等于已经验证的脱涡基频。')+'</p>'+
        '<pre>Fs = 1 / Δt_sample;  f_Nyquist = Fs / 2\nf_k = k Fs / N;  Δf = Fs / N = 1/(N Δt_sample)\nY_k = FFT(Cl)_k;  A_k = |Y_k| / N\nSingle-sided: double positive-frequency bins, except DC and even-N Nyquist.\nSt = f_s D / U∞</pre>'+
        '<p>'+t('Adaptive solver timesteps can produce nonuniform force samples. The dialog tests spacing and explicitly reports linear resampling to the median interval before FFT when needed. This is uniform-time resampling, not denoising. Saved U,p frame spacing is separate from force sampling. Nonuniform cases would need a different spectral method if resampling is unacceptable.','自适应求解步长可能使力系数采样不等间隔。对话框检查间距，必要时明确说明按中位间隔线性重采样后进行 FFT。这是等时间重采样，不是去噪。U,p 场保存间隔与力系数采样不同。若不能接受重采样，需选择其他非均匀频谱方法。')+'</p>'+
        '<p>'+t('Require many stationary shedding cycles, adequate sample rate and a common late-time window before reporting St. A peak spread across neighbouring bins can be finite-record leakage; harmonics occur near integer multiples, while transient and modulation peaks need time-history evidence. Nyquist prevents aliasing only when the sampled signal is appropriately band-limited. These validation records are too short for a defensible shedding St.','报告 St 前需足够多的稳定脱涡周期、足够采样率与统一后期窗口。主峰扩散到邻近 bin 可由有限记录谱泄漏造成；谐波接近整数倍，瞬态或调制峰需要结合时域证据判断。仅在信号适当带限时，奈奎斯特条件才能避免混叠。本次短测试不足以给出可信脱涡 St。')+'</p>')
    rows=[]
    for r in V['rounds']:
        n=r['genuine_frames']; cells=r['cells']
        rows.append([r['round'],r['case'],cells,r['cores'],r['solver_end_s'],n,r['solver_elapsed_seconds'],f'{n*cells} × 6 / {n*cells} × 8','PASS'])
    q=V['rounds'][0]['quality']
    section('verification',t('10 · Measured release validation','10 · 本版本实测验证'),
        '<div class="success">'+t('Three real 3D cylinder end-to-end runs passed. GUI draw/undo/region operations, CPU-budgeted submission, OpenFOAM mesh quality, four-rank solve, reconstruction, actual VTK files, finite CSV/MAT fields and GIF were checked.','三轮真实三维圆柱全流程测试通过：验证 GUI 绘图/撤销/区域操作、CPU 预算提交、OpenFOAM 网格质量、四核求解、重建、真实 VTK 文件、CSV/MAT 有限场值与 GIF。')+'</div>'+
        table([t('Round','轮次'),t('Actual case','实际算例'),t('Cells','单元'),'MPI',t('End / s','结束 / s'),t('Frames','帧数'),t('Measured wall / s','实测耗时 / s'),'MAT xytuvp / xyztuvwp',t('State','状态')],rows)+
        '<p>'+t('Measured wall time is the Linux off.start–off.end interval covering solve and reconstruction/export; it excludes Windows pre-generation, most meshing and independent export QA. Full workbench test duration is longer. The three cases use the same 5120-cell topology with different durations / output intervals (0.01, 0.02 and 0.1 s). They are repeat workflow tests, not a mesh-convergence study.','实测耗时为 Linux off.start–off.end，包含求解、重建与导出，不含 Windows 预生成、大部分划网格与独立导出核验。整套软件测试耗时更长。三例使用同一 5120 单元拓扑，时长和输出间隔不同（0.01、0.02、0.1 s），属于重复流程测试，不是网格收敛研究。')+'</p>'+
        table([t('Actual metric','实测指标'),t('Result','结果')],[['Max skewness',f'{q["max_skewness"]:.10g}'],['Max non-orthogonality / °',f'{q["max_nonorthogonality_deg"]:.8g}'],[t('Skewness > 0.5 / non-orthogonality > 30°','skewness > 0.5 / 非正交 > 30°'),'0 / 0'],[t('Nonpositive-volume cells','非正体积单元'),'0'],[t('Worst skew face / XYZ m','最坏 skew 面 / XYZ m'),str(q['worst_skew_face'])+' / '+str(q['worst_skew_xyz'])],[t('Pause test simulated time before / after 1.5 s','暂停前 / 等待 1.5 s 后模拟时间'),str(V['pause_resume']['before'])+' / '+str(V['pause_resume']['after_1p5_seconds'])],[t('Maximum reserved cores','最大占用预算核数'),V['max_reserved_cores']]])+
        '<p>'+t('Independent max skewness agrees with checkMesh within 1e−7; the ~1.7e−6° non-orthogonality is floating-point round-off on a radial orthogonal grid. True saved times and four z-centre planes were asserted. Evidence is reproducible; no CFD frames were interpolated for export.','独立最大 skewness 与 checkMesh 误差小于 1e−7；约 1.7e−6° 的非正交角是径向正交网格的浮点舍入。测试断言真实保存时间与四个 z 中心层，没有为导出插值合成 CFD 帧。')+'</p>'+
        '<p>'+link('../evidence/validation.json',t('Raw validation JSON','原始验证 JSON'))+' · '+link('../evidence/round3.mat','Round 3 MAT')+' · '+link('../evidence/round3.csv','Round 3 CSV')+' · '+link('../evidence/round3.gif','Round 3 GIF')+'</p>'+
        '<pre>..\\runtime\\Scripts\\python.exe tests\\validate_release.py\n# Generates three new cases, never overwrites existing ones.</pre>')
    if (E/'additional_validation.json').exists():
        extra=json.loads((E/'additional_validation.json').read_text())
        extra_rows=[[x['method'],x['quality']['cells'],x['quality']['skewness'],x['quality']['non_orthogonality'],x['threshold_skew'],x['threshold_nonortho'],x['state']] for x in extra['meshes']]
        body='<p>'+t('Additional actual GUI-worker tests exercised consecutive Gmsh and manual-block submissions. Mesh quality thresholds are shown explicitly: a mesh passing a looser threshold is not presented as meeting the strict cylinder gate.','额外实测通过 GUI 后台线程连续提交 Gmsh 与手动分块。表中明确列出质量阈值，宽松门槛通过不能当作满足圆柱严格门槛。')+'</p>'+table([t('Method','方法'),'Cells','Max skew','Max angle / °','Skew limit','Angle limit / °','State'],extra_rows)+'<p>'+t('Two independent two-rank MPI solver cases were observed RUNNING at the same time under a four-core budget and both reached DONE. The maximum reservation was four cores.','在总预算四核下，实测观察到两个独立两核 MPI 算例同时处于 RUNNING，最后均为 DONE，最大预算占用为四核。')+'</p>'
        if (E/'checkpoint_validation.json').exists():
            recovery=json.loads((E/'checkpoint_validation.json').read_text())
            body+='<p>'+t('Checkpoint fault injection stopped only a verified test-case MPI tree. Recovery resumed from genuine matching saved processor fields at ','检查点故障注入仅终止经过核验的测试算例 MPI 进程树，恢复读取所有 processor 一致的真实保存场，起始时刻为 ')+str(recovery['complete_checkpoint_time_s'])+t(' s, reached ',' s，最终推进至 ')+str(recovery['final_time_s'])+t(' s and exported successfully without remeshing. This was process interruption, not an actual host reboot.',' s 并成功导出，没有重新划网格。本次是进程中断测试，不是实际重启电脑。')+'</p>'
        section('additional',t('11 · Additional implementation checks','11 · 额外实现检查'),body)
    professional=json.loads((E/'professional.json').read_text())
    section('professional',t('0.4 · Construction tools, spacing and initial files','0.4 · 绘图工具、间距与初始文件'),
        '<ol><li>'+t('Geometry → Line: drag between two snapped endpoints. Polyline: click vertices; Enter or double-click finishes; Escape cancels. Exact line opens coordinate pairs in metres. Double-click a stored curve to edit its points. Undo/redo, duplicate, move and delete include curves. Orange dashed curves are construction references: they do not cut the fluid domain. Closed arbitrary polygon obstacles remain future work.','几何 → 直线：拖动两个吸附端点。折线：逐点点击，Enter 或双击完成，Esc 取消。精确直线允许按米输入坐标。双击已有曲线编辑点列；支持撤销、重做、复制、移动和删除。橙色虚线为辅助参考，不切割流体域；任意闭合多边形实体仍待开发。')+'</li><li>'+t('Draw a Mesh region, then open Mesh spacing. Choose O-grid radial grading or R1/R2, Uniform / Increasing / Decreasing, direction and coarse/fine ratio. Preview displays the formula and endpoint values. For radial blocks, q=R^(1/(N−1)); h_i=L q^i / Σq^j. R means last-cell / first-cell width, not adjacent-cell ratio. R&lt;1 decreases spacing.','先绘制网格区域，再打开网格间距。选择 O 网格径向或 R1/R2、均匀/递增/递减、方向和粗细比。预览显示公式与首尾值。径向分块 q=R^(1/(N−1))，h_i=L q^i / Σq^j；R 是末单元/首单元宽度比，不是相邻单元比。R&lt;1 表示递减。')+'</li><li>'+t('Region Gmsh targets use h(s)=h_start R^s with s clamped to [0,1]. A negative direction measures s from the opposite edge. Blending, background size caps, curvature and competing regions affect the generated size. A size-field request is not proof that each unstructured cell edge is strictly monotone. Structured partitioned boxes propagate shared subdivisions and restart grading per segment. Verify generated quality before solving.','Gmsh 区域目标为 h(s)=h_start R^s，s 限制在 [0,1]；负方向从相反边缘计量。平滑混合、背景尺寸上限、曲率和重叠区域会改变生成尺寸。尺寸场请求不能证明非结构网格每条边都严格单调。结构分块会传播共形分割并在每段重启渐变。求解前检查实际网格质量。')+'</li><li>'+t('Initial fields / dictionaries opens a local draft at 0/U before submission. Save each edited file, then close to apply differences to the project. Overrides are serialized in the project and written to each new case. Change Flow settings first; raw overrides persist and can supersede those settings. Pressure p is kinematic m²/s². Formatting preserves tokens; a structure check is not OpenFOAM semantic validation. Running cases cannot be edited through the case editor.','提交前点击初始场/字典，从本地草稿的 0/U 开始编辑；每个文件修改后保存，关闭时将差异应用至项目。覆盖内容随项目保存并写入新算例。应先修改物理参数；原始字典覆盖会持续存在并可能优先于界面值。p 为运动学压力 m²/s²。格式化保留 token；结构检查不能代替 OpenFOAM 语义核验。真实活动算例禁止通过算例编辑器修改。')+'</li><li>'+t('Desktop and Start Menu contain a native Open Foam Friend icon. The root launcher reads LATEST.txt; old timestamped releases remain available. install.ps1 recreates shortcuts on another Windows PC.','桌面与开始菜单提供原生 Open Foam Friend 图标。根启动器读取 LATEST.txt；历史时间戳版本保留。另一台 Windows 电脑执行 install.ps1 可重建快捷方式。')+'</li></ol>'+pic('professional_EN.png',t('Actual desktop geometry workspace with new drawing and setup controls.','真实桌面几何工作区及新增绘图/设置工具。'))+
        '<p>'+link('../evidence/professional.json',t('Measured feature checks; remote verification status','实测功能核验与远程验证状态'))+'</p>')
    section('ssh',t('SSH / Slurm setup and submission','SSH / Slurm 配置与提交'),
        '<div class="notice">'+t('Remote execution has not been validated against a real cluster. Local tests verify host-key enforcement, bundle contents and Bash syntax only. Slurm is supported; PBS is not implemented in this release.','尚未在真实超算验证远程运行。本地测试仅核验主机密钥策略、上传包内容与 Bash 语法。本版支持 Slurm，尚未实现 PBS。')+'</div><ol><li>'+t('Settings → SSH / Slurm supercomputer. Enter a host or existing SSH config alias, optional username/key, remote root, site OpenFOAM environment command, partition/account, MPI ranks and walltime. Use a local key or SSH agent. Do not paste secrets into reports.','设置 → SSH / Slurm 超算。填写主机或 SSH 配置别名、可选用户名/密钥路径、远程根目录、站点环境命令、分区/项目、MPI 进程数和最长时间。使用本机密钥或 SSH 代理，不把秘密写入报告。')+'</li><li>'+t('First verify the host fingerprint through your institution and establish known_hosts using normal ssh. The GUI uses BatchMode and StrictHostKeyChecking=yes; it will reject unknown or changed keys. Save & test is read-only and checks foamRun/sbatch/squeue.','先经学校/机构验证主机指纹，再用普通 ssh 建立 known_hosts。GUI 使用 BatchMode 与 StrictHostKeyChecking=yes，拒绝未知或变化的密钥。保存并测试只读检查 foamRun/sbatch/squeue。')+'</li><li>'+t('Choose an inactive real case with 0, system, constant and either polyMesh or blockMeshDict. Preview the generated Slurm script. Upload copies only those three directories and the reviewed script; it does not upload processor fields or old time folders. Remote existing case folders are protected. To rerun, use a new case name/directory. External include dependencies are not bundled automatically.','选择非活动真实算例，须有 0/system/constant，及 polyMesh 或 blockMeshDict。预览生成的 Slurm 脚本。仅上传这三个目录和审阅脚本，不上传 processor 场或旧时间目录。远程已有目录受保护；重跑须换算例名称/目录。外部 include 依赖不会自动打包。')+'</li><li>'+t('Confirm that srun or mpirun matches site MPI configuration. Edit the exact script if needed, then press Upload & submit. A successful numeric sbatch ID is recorded; failures remain visible in the log. Scheduler refresh batches squeue/sacct queries and polls at ≥30 s. Hold/release applies to pending jobs. Cancel invokes scancel after confirmation. Running-job suspend/resume, result download and PBS are future work.','确认 srun 或 mpirun 符合站点 MPI 配置。必要时编辑当前脚本，再点击上传提交。仅在 sbatch 返回数字 ID 后记录提交成功；失败显示日志。squeue/sacct 查询按组批量执行，轮询至少 30 秒。hold/release 针对排队作业；取消确认后调用 scancel。运行中暂停/继续、结果下载和 PBS 仍待开发。')+'</li><li>'+t('The submitted script checks mesh quality, sets the decomposition count, solves, reconstructs and exports actual VTK. This is a clean run using initial fields, not a remote restart service. Site quotas, scheduler queue times and permissions may reject commands. Scheduler elapsed/walltime are not a trustworthy physics completion ETA.','提交脚本检查网格质量、设置并行分区数、求解、重建并导出真实 VTK。这是使用初始场的新计算，不是远程检查点恢复服务。站点额度、队列和权限可能拒绝命令；调度器已用时间/限时不能当成可信的物理计算完成预估。')+'</li></ol>'+pic('ssh_EN.png',t('Actual SSH configuration dialog.','真实 SSH 配置窗口。'))+'<p>'+link('https://slurm.schedmd.com/sbatch.html','Slurm sbatch')+' · '+link('https://slurm.schedmd.com/squeue.html','Slurm squeue')+' · '+link('https://slurm.schedmd.com/scontrol.html','Slurm scontrol')+'</p>')
    section('hci',t('0.5 · Drawing interaction','0.5 · 绘图交互'),
        '<p>'+t('Lines and rectangles use drag. Circle uses centre and radius: press at the centre, drag to the radius and release. Polyline uses clicks; Enter, double-click or right-click finishes. Backspace / Ctrl+Z removes the last draft vertex. Escape first cancels the draft while retaining the tool; a second Escape selects. Tools remain active for repeated drawing.','直线和矩形使用拖动。圆采用圆心/半径：在圆心按下，拖至半径点后松开。折线逐点点击；Enter、双击或右键完成。Backspace/Ctrl+Z 撤回最后一个草稿顶点。Esc 先取消草稿并保留工具，再按一次返回选择。工具保留激活，可连续绘制。')+'</p><p>'+t('F3 toggles endpoint/midpoint/centre/quadrant snaps; F9 toggles grid snap. Object snap uses a 9-pixel aperture independent of zoom. Shift or F8 constrains line directions horizontally/vertically. Alt temporarily disables snapping. The crosshair indicates the acquired point and the live label shows length/angle/diameter/width/height. Middle-button drag pans without changing the drawing tool; wheel zoom follows the pointer. V/H/L/P/C/R/G/M select the corresponding tools when the canvas has focus. Ruler clicks do not create objects.','F3 开关端点/中点/圆心/象限点吸附；F9 开关网格吸附。对象吸附范围为 9 像素，与缩放无关。Shift 或 F8 约束直线水平/垂直。Alt 临时关闭吸附。十字标记显示吸附位置，动态标签显示长度/角度/直径/宽高。中键拖动平移而不改变绘图工具；滚轮以指针为中心缩放。画布拥有焦点时 V/H/L/P/C/R/G/M 切换工具。点击标尺不会生成对象。')+'</p><p>'+t('This is tested interaction functionality, not a formal usability study. Construction curves still do not form arbitrary solid obstacles. Remote Slurm remains untested against a real cluster. The previous strict-shell environment incompatibility is corrected by avoiding nounset during OpenFOAM setup; the local environment now loads successfully.','本次验证操作功能，不代表完成正式用户可用性研究。辅助曲线仍不构成任意实体。真实超算 Slurm 仍未实测。已修正上一版严格 Shell 环境兼容问题，OpenFOAM 加载时不启用 nounset，本机环境探测成功。')+'</p>'+pic('hci_EN.png','Actual live drawing preview / 真实绘图预览')+pic('hci_ZH.png','Chinese controls / 中文控制')+'<p>'+link('../evidence/hci_validation.json','Interaction test evidence')+' · '+link('https://doc.qt.io/qt-6/qgraphicsview.html','Qt Graphics View')+' · '+link('https://help.autodesk.com/cloudhelp/2023/ENU/AutoCAD-MAC-GettingStarted/files/GUID-85D8C41C-9C3E-440F-BD60-61848DD27219.htm','Autodesk precision controls')+'</p>')
    section('navigation',t('0.6 · Tree and compact workspace tabs','0.6 · 对象树与紧凑工作区标签'),
        '<p>'+t('A conventional compact tab strip switches Pre-processing / Computation / Post-processing. The left simulation tree remains for objects and detailed settings. Current tab uses a white background, bold text and a narrow underline; a small Current label provides location feedback. Large navigation cards and banner actions have been removed.','使用常规紧凑标签栏切换前处理 / 计算 / 后处理。左侧对象树保留，用于对象与详细参数。当前标签使用白底、加粗文字与细下划线，旁边以小文字显示当前位置。已移除大导航卡片和说明操作横幅。')+'</p><p>'+t('Ctrl+1/2/3 switches the three stages. Clicking a tab does not submit a job or clear the design. Drawing tools appear only in preparation; simulation and result controls follow their workspaces. The tabs still work when the tree is hidden.','Ctrl+1/2/3 切换三个阶段。点击标签不会提交任务或清空设计。绘图工具仅在前处理显示，计算与结果工具对应各自工作区。对象树隐藏后标签仍可正常切换。')+'</p>'+pic('navigation_0_EN.png','Actual compact tabs with object tree / 真实紧凑标签与对象树')+pic('navigation_1_ZH.png','Chinese post-processing workspace / 中文后处理界面')+'<p>'+link('../evidence/navigation_validation.json','Actual navigation checks')+' · '+link('https://www.nngroup.com/articles/ten-usability-heuristics/','NN/g usability heuristics')+'</p>')
    section('designbasis',t(('12' if (E/'additional_validation.json').exists() else '11')+' · Industrial references and design choices',('12' if (E/'additional_validation.json').exists() else '11')+' · 工业软件参考与设计依据'),
        '<p>'+t('The design borrows workflow principles, not proprietary implementations: staged geometry→mesh→solve guidance from Ansys; a shared object tree from SALOME; wall-spacing/orthogonality inspection from Pointwise; persistent view/field/time controls from ParaView. Qt Graphics View supplies native sketch interaction, Gmsh provides OCC operations and size fields, and VTK provides the real result rendering.','设计借鉴流程原则，不复制专有实现：Ansys 的几何→网格→求解阶段引导、SALOME 的共享对象树、Pointwise 的壁面间距与正交性检查、ParaView 的视图/场/时间控制。Qt Graphics View 实现原生绘图交互，Gmsh 提供 OCC 几何和尺寸场，VTK 负责真实结果渲染。')+'</p>'+
        '<p>'+t('Recommended next engineering priorities: constrained sketch dimensions and richer block topology; independent 3D CAD import; boundary-layer/y+ tools; long-window convergence studies; streaming exports; automated installer and physical second-PC tests. These are not presented as existing features.','后续工程优先建议：约束尺寸与更丰富块拓扑、独立三维 CAD 导入、边界层/y+ 工具、长窗口收敛研究、流式导出、自动安装器和实体第二台电脑测试。这些不列为已实现功能。')+'</p>'+
        '<ol>'+''.join('<li>'+link(url,title)+'</li>' for title,url in sources)+'</ol>')
    section('docking-ssh',t('0.7 · Movable tabs and SSH configuration','0.7 · 可拖动选项卡与 SSH 配置'),
        '<p>'+t('The workspace tab strip starts at the bottom on a fresh profile. Drag its left grip into the upper or lower half of the application and release to dock at the top or bottom. Releasing outside the window cancels. Right-click the strip also provides top/bottom commands. Position is saved across restarts; Settings → Reset workspace layout restores bottom placement without deleting your project.','新配置默认把工作区标签放在下方。拖动最左侧手柄，在软件上半部或下半部松开，分别停靠到上方或下方；窗口外松开取消。右键标签栏也可选择上下停靠。位置在重启后保留；设置 → 重置界面布局恢复下方默认位置，不删除项目。')+'</p>'+pic('tabs_default_bottom_ZH.png',t('Actual compact bottom tabs and retained object tree.','真实下方紧凑选项卡与对象树。'))+pic('tabs_dragged_top_EN.png',t('Actual pointer drag to top placement.','实际鼠标拖动到上方后的界面。'))+
        '<h3>'+t('SSH / Slurm setup','SSH / Slurm 配置')+'</h3><p>'+t('Settings → SSH / Slurm supercomputer opens a non-blocking configuration and job panel. First log in with your site-provided host and username in a terminal and verify its fingerprint with the site. Use an existing local private key or ssh-agent; the application does not store passwords. Fill the fields below, save and test, select an inactive real OpenFOAM case, generate the batch script, review it, then submit.','设置 → SSH / Slurm 超算打开非阻塞的配置与任务面板。先在终端用超算提供的主机与用户名登录，并向超算核对指纹。使用已有本机私钥或 ssh-agent；软件不保存密码。填写下方参数，保存并测试，选择非活动的真实 OpenFOAM 算例，生成并审阅脚本后提交。')+'</p>'+table([t('Field','字段'),t('Meaning','含义')],[
        ['Host / User / Port',t('Site login host or SSH config alias, username and port.','超算登录主机或 SSH 配置别名、用户名和端口。')],
        ['Identity',t('Existing local key path; empty uses SSH config/agent. The key is never uploaded.','已有本机密钥路径；留空使用 SSH 配置或代理，不上传密钥。')],
        ['Remote root',t('Writable absolute scratch directory, e.g. /scratch/yourname/off.','可写的绝对 scratch 目录，例如 /scratch/yourname/off。')],
        ['Environment',t('The actual site module load or source command for Foundation OpenFOAM. Do not assume your WSL path exists remotely.','该超算实际的 Foundation OpenFOAM module load 或 source 命令，不要套用本机 WSL 路径。')],
        ['Partition / Account',t('Queue and allocation project supplied by the cluster; omit only if the site allows.','超算提供的队列与配额项目，仅在超算允许时留空。')],
        ['Walltime / Cores / Launcher',t('Requested time limit in HH:MM:SS, MPI ranks and site-compatible srun/mpirun. Walltime is a limit, not an ETA.','请求时限 HH:MM:SS、MPI 进程数及集群适用的 srun/mpirun。时限不是预计耗时。')],
        ['Poll seconds',t('At least 30 seconds; 60 is the default.','至少 30 秒，默认 60 秒。')]])+pic('ssh_configuration_EN.png',t('Actual SSH configuration controls and setup instructions.','真实 SSH 配置控件与说明。'))+
        '<p>'+t('Save & test is read-only and checks foamRun, sbatch and squeue. Upload transfers 0, system and constant, including existing polyMesh, then submits the exact reviewed script. The scheduler table displays status, elapsed and scheduler details. Hiding this panel keeps polling while the main app is open. On restart saved remote records resume polling. Exiting the app does not cancel remote jobs. Hold/release applies to pending jobs; cancellation requires confirmation.','保存并测试为只读操作，检查 foamRun、sbatch 和 squeue。上传包括 0、system、constant 及已有 polyMesh，执行的是当前审阅的脚本。调度表显示状态、已用时间与调度信息。隐藏面板后，主程序开启时仍继续轮询；重启后已有远程记录恢复轮询。退出软件不会取消超算作业。hold/release 用于排队作业，取消需确认。')+'</p>'+
        '<p>'+t('Verification: actual toolbar pointer drag in both directions, position restoration, reset and dialog lifecycle passed. SSH polling lifecycle used a clearly labelled fixture transport. No real supercomputer was contacted or submitted to. Real site MPI, quotas and scheduler configuration still need validation. PBS, automatic remote result download and running-job suspension are not implemented.','验证：实际鼠标双向拖动、位置恢复、重置与窗口生命周期通过；SSH 轮询生命周期使用明确标注的接口测试数据，未连接或提交真实超算。真实集群的 MPI、配额及调度配置仍需验证。未实现 PBS、远程结果自动下载及运行作业暂停。')+'</p><p>'+link('../evidence/docking_ssh_validation.json',t('Raw docking and SSH lifecycle evidence','停靠与 SSH 生命周期原始证据'))+' · '+link('https://doc.qt.io/qt-6/qtoolbar.html','Qt QToolBar')+' · '+link('https://slurm.schedmd.com/sbatch.html','Slurm sbatch')+'</p>')
    section('dimensions-selection',t('0.8 · Selection and 2D / 3D design','0.8 · 鼠标选择与二维 / 三维设计'),
        '<p>'+t('This is an additive release: the existing drawing tools, object tree, mesh methods, guide, movable workspace tabs, job queue, dictionaries, post-processing exports and SSH remain. Click Select or press V while the sketch has focus. Click the body or its text label to select; the selected geometry is orange and the selected object is named above the canvas. Ctrl-click adds/removes selection. Selection is preserved when the view is rebuilt or the interface language changes; it does not create an undo entry. Existing object movement and drawing shortcuts are retained.','此版为增加与修复：保留已有绘图、对象树、网格方法、引导、可停靠选项卡、队列、字典、后处理导出和 SSH。在绘图板内点击选择工具或按 V，点击实体或文字标签即可选择；选中几何呈橙色，画布上方显示对象。Ctrl 点击可增减选择。刷新视图或切换语言保留选中对象，选择本身不产生撤销记录。原有移动对象和绘图快捷键保留。')+'</p>'+pic('selection_XY_EN.png',t('Actual selected object in the XY sketch.','真实 XY 绘图板对象选择。'))+
        '<p>'+t('The new model/domain button sits above the pre-processing view. Select 2D or 3D explicitly, set Z depth and spanwise layers, then confirm. 2D writes one empty spanwise layer; 3D creates a true volume mesh with the selected layer count. The pre-processing view selector switches between editable XY sketch and 3D extrusion model. 3D supports wheel zoom, drag orbit and click-to-select solids synchronized with the sketch. Domain controls are still available from the original inspector/tree.','新增模型 / 流场按钮位于前处理视图上方。明确选择二维或三维，设置 Z 深度和展向层数后确认。二维写入一层 empty，三维生成指定层数的真实体网格。视图选择器在可编辑 XY 截面与三维拉伸模型间切换。三维支持滚轮缩放、拖动旋转、点击实体选择，并与绘图板同步。原来的右侧面板和对象树入口仍保留。')+'</p>'+pic('dimension_controls_ZH.png',t('Actual dimension and design-view controls.','真实维度与设计视图入口。'))+pic('design3D_geometry.png',t('Actual VTK extrusion of the project geometry; geometry preview, not generated CFD mesh.','项目几何实际 VTK 拉伸：设计预览，不是已生成的 CFD 网格。'))+
        '<p>'+t('Supported 3D design is an XY section extruded along Z: circle→cylinder, rectangle→prism, triangle→triangular prism. Arbitrary 3D CAD solids and booleans remain unimplemented. Quality and result views still use actual generated OpenFOAM meshes and saved fields. A further real 2D 1280-cell/four-core solve and finite MAT export verifies the one-layer path, alongside three real 5120-cell/four-core 3D pipeline tests.','当前三维设计为 XY 截面沿 Z 拉伸：圆→圆柱，矩形→棱柱，三角形→三棱柱。任意三维 CAD 实体与布尔建模尚未实现。质量与结果视图仍读取真实 OpenFOAM 网格及保存场。额外真实二维 1280 单元 / 4 核求解和有限值 MAT 导出验证一层路径，同时进行三轮真实三维 5120 单元 / 4 核流程验证。')+'</p><p>'+link('../evidence/selection_dimensions_validation.json',t('Pointer selection and extrusion evidence','鼠标选择与拉伸证据'))+' · '+link('../evidence/twoD_pipeline_validation.json',t('Actual 2D solver evidence','真实二维求解证据'))+'</p>')
    section('workspace-upgrade',t('0.9 · Project workspace, terminal and genuine field playback','0.9 · 项目工作台、终端与真实场播放'),
        '<p>'+t('Welcome / Projects opens recent reproducible project JSON files, creates a 2D or 3D cylinder project and links to both manuals. Its startup checkbox is optional. Two-click Line: choose Line, click the first point, release, move and click the endpoint. Esc cancels; Undo reverts. Press-drag-release and the original polyline/object-selection features remain. Lines are construction guides; arbitrary CAD booleans are not implemented.','欢迎 / 项目管理可以打开最近项目 JSON、新建二维或三维圆柱，并访问中英教程；启动显示可选。两点直线：选直线，点击第一点并松开，移动后点击第二点，Esc 取消、撤销回退。原拖动绘线、折线和对象选择仍保留。直线为构造线，任意 CAD 布尔操作尚未实现。')+'</p>'+pic('welcome.png',t('Actual optional project welcome dialog','实际可选项目欢迎页'))+
        '<p>'+t('Pre-processing → Design parameters / mesh code provides validated, editable project JSON plus read-only generated blockMeshDict (or Gmsh generator). Initial fields / dictionaries remains the editor for U, p and numerical schemes. All design values use SI. Formatting preserves OpenFOAM function-key adjacency such as div(phi,U); solver parsing was verified by the actual runs. Dictionary overrides have precedence over generated values: review them before submitting.','前处理 → 设计参数 / 网格代码提供经过验证的可编辑项目 JSON，以及只读 blockMeshDict 或 Gmsh 生成器源代码；初始场 / 字典保留 U、p 和离散格式编辑。参数采用 SI。排版保留 div(phi,U) 等关键字内部连接，并由真实求解验证解析。显式字典覆盖优先于界面生成值，提交前应检查。')+'</p>'+
        '<p>'+t('Project → Detect WSL / OpenFOAM scans installed distributions, user home, available CPUs, bashrc and run folders. Applying a detected profile first verifies foamRun. Foundation 14 is the validated solver target; other versions need compatibility checks. Settings → WSL Terminal opens a dockable persistent Bash console: Connect, type commands, Enter, Up/Down history, Ctrl+C button, exit to close the shell. The terminal starts in the selected Linux working directory. It is a plain-text command console, not a complete VT/ncurses emulator. Do not paste secrets into exported logs.','项目 → 自动探测 WSL / OpenFOAM 扫描发行版、用户目录、CPU、bashrc 和 run 目录；所选配置在应用前验证 foamRun。本版验证目标为 Foundation 14，其他版本需兼容性验证。设置 → WSL 终端打开可停靠的持续 Bash 控制台：连接、输入命令回车、上下键历史、Ctrl+C 按钮、exit 退出。可选 Linux 工作目录。这是纯文本命令控制台，并非完整 VT/ncurses 终端。不要将密钥粘贴进导出的日志。')+'</p>'+
        '<p>'+t('Post-processing offers Play/Pause, previous/next saved frame, loop and 0.1×–50× physical-time playback rates. It does not manufacture interpolated fields or change CFD deltaT. Select p, U, u, v, w, speed, vorticity, its components or magnitude. Curl(U) is a VTK spatial-gradient estimate in s⁻¹, not an additional solved OpenFOAM field. Boundary derivatives may be less accurate. A solid-body rotation test with exact curl=(0,0,4) verifies signs and values. Pressure remains kinematic m²/s². MAT retains xytuvp and xyztuvwp; use xyztuvwp for 3D PINNs.','后处理提供播放 / 暂停、上一帧 / 下一帧、循环和 0.1×–50×物理时间播放倍率；不制造插值场、不修改 CFD 内部步长。可选 p、U、u、v、w、速度模、涡量及分量 / 模。curl(U) 是 VTK 空间梯度估计，单位 s⁻¹，不是另一个 OpenFOAM 求解场，边界导数可能较不准确。刚体旋转解析 curl=(0,0,4) 验证符号和值。压力为运动学压力 m²/s²。MAT 保留 xytuvp 和 xyztuvwp，三维 PINN 使用后者。')+'</p>'+pic('workspace_upgrade_EN.png',t('Qt controls capture; the native OpenGL child is excluded from QWidget.grab','Qt 控件截图；QWidget.grab 不包含原生 OpenGL 子窗口'))+pic('workspace_vorticity_frame.png',t('Direct VTK framebuffer of genuine vorticity_z data','真实涡量 z 分量的直接 VTK 帧缓冲截图'))+
        '<p>'+t('Both 3D scenes offer ISO and ±X/±Y/±Z orientations, orthographic projection, wheel zoom and trackball orbit. The busy progress indicator represents work in progress, not invented percentage completion. Buttons show pressed feedback; the initiating button is disabled during its background task. Open result, CSV, MAT, WSL probing and case-copy work run in background workers. GIF renders on the GUI thread while servicing paint events.','两个三维视图均提供 ISO、±X / ±Y / ±Z 对齐、正交投影、滚轮缩放和轨迹球旋转。加载条表示任务正在处理，不虚构完成百分比。按钮显示按下反馈，后台任务运行期间禁用发起按钮。结果载入、CSV、MAT、WSL 探测和算例复制由后台线程执行；GIF 在界面线程渲染并处理绘制事件。')+'</p>'+
        '<p>'+t('Postprocess → Export complete .foam case folder copies the reconstructed serial mesh, dictionaries, genuine field directories, force history and logs to a new protected folder, then opens Explorer. A .foam marker alone is not CFD data. export_manifest.json lists actual field times. Export verification reopens this folder through VTK and checks 5120 cells / 6 genuine frames. Three fresh four-rank 5120-cell 3D cylinder tests, plus a separate 2D solve, check this release; these short runs verify the software pipeline, not physical grid convergence or statistically converged cylinder forces.','后处理 → 导出完整 .foam 算例文件夹将重构后的串行网格、字典、真实时间场目录、力历史与日志复制到受保护的新文件夹并打开资源管理器。.foam 空标记本身不是 CFD 数据；export_manifest.json 列出实际场时间。导出验证用 VTK 重新打开该文件夹并检查 5120 单元 / 6 帧真实数据。本版三轮新三维 5120 单元 / 4 核圆柱算例及额外二维求解检查软件流程；这些短算例用于软件验收，不代表物理网格收敛或圆柱力的统计收敛。')+'</p><p>'+link('../evidence/workspace_upgrade_validation.json',t('Current controls and export evidence','本版控件与导出证据'))+' · '+link('https://vtk.org/doc/nightly/html/classvtkGradientFilter.html','VTK gradient / curl reference')+' · '+link('https://doc.qt.io/qtforpython-6.10/PySide6/QtCore/QProcess.html','Qt process console reference')+'</p>')
    section('button-feedback',t('Button states: mode, dialog and background work','按钮状态：绘图模式、对话框与后台任务'),
        '<p>'+t('Toolbar commands use compact outline icons and text. Idle buttons have no surrounding frame; hover gives a light tint, the selected mode has a narrow underline, and pressed commands give immediate feedback. A dialog command stays checked until its dialog closes; a background command stays checked and disabled until its worker finishes. This does not turn a one-shot command into a persistent drawing mode. Drawing modes remain exclusive and visibly checked until another mode is selected.','工具栏使用紧凑线条图标与文字，闲置按钮不加外框；悬停轻微变色，选中工具显示细下划线，按下操作有即时反馈。打开对话框的按钮在对话框关闭前持续高亮，后台操作按钮保持高亮并禁用直到任务结束；这不代表一次性命令变成持续绘图模式。绘图模式为互斥选择，切换到其他工具前持续标明当前选项。')+'</p>'+pic('button_command_active.png',t('Actual dialog command active state','实际对话框操作的执行状态'))+pic('button_tool_selected.png',t('Actual selected drawing mode','实际当前绘图模式'))+'<p>'+link('../evidence/button_feedback_validation.json',t('Pointer and asynchronous button-state tests','实际鼠标与异步按钮状态测试'))+'</p>')

    section('colourmap',t('0.10 · User-controlled colour map and legend','0.10 · 自定义配色与色标'),
        '<ol><li>'+t('Open a genuine result, choose a scalar/vector field, then click Colour map… beside the view controls (or use the scene right-click menu). Mesh-only view disables the colour editor.','打开真实结果并选择场，点击视图控件旁的“色标设置”，也可使用场景右键菜单。纯网格视图禁用色标编辑。')+'</li><li>'+t('Choose Viridis, Cividis, Blue–red, Grey, legacy Rainbow or Turbo; reverse if required. Auto range follows the actual current frame. For honest visual time comparisons, click Use current data range as fixed limits, or enter a fixed minimum/maximum in scientific notation.','可选 Viridis、Cividis、蓝红、灰度、传统彩虹和 Turbo，并可反转。自动范围跟随真实当前帧；比较不同时刻时，可将当前数据范围冻结或用科学计数法输入固定最小/最大值。')+'</li><li>'+t('Positive fixed limits are required for log scale. A log range cannot cross zero. Outside-range values use end colours; no CFD values are clipped or modified.','对数色标须使用正值固定范围，不能跨零。超范围数据使用端点颜色，不截断或修改 CFD 数值。')+'</li><li>'+t('Legend & layout controls title, tick count, numeric precision/format, font sizes, vertical/horizontal orientation and normalized viewport position/size. Position is measured from the bottom-left. Apply updates the actual VTK legend; OK applies and closes; Cancel discards unapplied controls. Settings are independent per field and persist across sessions.','“色标与布局”可设置标题、刻度数量、数字格式/精度、字号、横竖方向和归一化视口位置/尺寸。位置从左下角计算。应用更新真实 VTK 色标；确定应用并关闭；取消放弃未应用的修改。各场设置独立并跨会话保存。')+'</li><li>'+t('PNG and genuine-frame GIF exports use the displayed palette and fixed range. Verify units and title before sharing a figure.','PNG 与真实帧 GIF 使用当前显示配色及固定范围，分享图像前请核对单位和标题。')+'</li></ol>'+pic('colour_dialog_EN.png',t('Actual scientific range and legend dialog','实际科学范围与色标设置对话框'))+pic('colour_fixed_pressure.png',t('Actual pressure field with user-set reversed blue–red palette and a fixed horizontal legend','真实压力场：用户设定的反转蓝红配色与固定水平色标'))+'<p>'+link('../evidence/colourmap_validation.json',t('Actual 11-frame colour/persistence/export tests','真实 11 帧色标、持久化与导出测试'))+' · '+link('https://vtk.org/doc/nightly/html/classvtkScalarBarActor.html','VTK scalar-bar reference')+'</p>')
    model_report=json.loads((E/'model_runtime_validation.json').read_text())
    runtime={row['model']:row for row in model_report['models']}
    model_rows=[]
    for name,model in MODELS.items():
        row=runtime[name]
        model_rows.append([model.family,name,', '.join(model.fields) or 'U, p',t(model.description,MODEL_DESCRIPTIONS_ZH[name]),'PASS · 4 MPI · 5120 · '+str(row['genuine_frames'] if 'genuine_frames' in row else len(row['frames']))+' '+t('frames','帧')])
    section('physics-models',t('0.10 · 24 verified incompressible model options','0.10 · 24 个不可压缩模型选项'),
        '<p>'+t('Flow & solver settings lists 1 no-turbulence option, 13 RAS, 6 LES and 4 hybrid DES/DDES/IDDES options. The factory list was checked against this host’s actual Foundation 14 source. Retained 0.11 evidence records all 24 options passing four genuine solver timesteps on a 5120-cell 3D cylinder with four MPI ranks, reconstruction and finite required-field CSV/VTK export. Twenty-three use installed built-in models; dynamicLagrangian uses the explicitly documented isolated compatibility implementation below.','“流动与求解设置”列出 1 个无湍流模型选项、13 个 RAS、6 个 LES 和 4 个混合 DES/DDES/IDDES 选项。清单与本机 Foundation 14 实际注册源码逐项核对。保留的 0.11 实测记录中，全部 24 个选项通过真实三维圆柱 5120 单元、4 MPI 核、4 个求解时间步，完成重构和所需场有限值 CSV/VTK 导出。其中 23 个使用安装自带模型，dynamicLagrangian 使用下述明确标注的独立兼容实现。')+'</p>'+pic('model_selector.png',t('Actual native physics-model selector and required-field explanation','实际原生物理模型选择器与所需场说明'))+table([t('Family','类型'),t('Canonical model','规范模型名'),t('Initial fields beyond U,p','U,p 以外初始场'),t('Scope','说明'),t('Integration test','流程实测')],model_rows)+
        '<div class="notice">'+t('The application currently solves transient incompressible Newtonian flow with PIMPLE; selecting a RAS model means URANS. LES/hybrid requires a 3D volume and at least two spanwise cells, but this minimum guard does not certify SGS resolution. SAS, LES and DES production use needs turbulence-resolution, timestep, wall treatment and statistical-window studies. DNS is not a menu model: no eddy viscosity plus adequate resolution of all relevant scales must be established separately. These tests are not validated cylinder force statistics or industrial certification. Compressible, multiphase and arbitrary rheology solver workflows are outside this release.','当前求解器为 PIMPLE 瞬态不可压缩牛顿流体，选择 RAS 即为 URANS。LES/混合模型要求三维体网格且至少两层展向单元，但最低准入条件不等于亚格子分辨率认证。SAS、LES、DES 正式科研应用仍须验证湍流分辨率、时间步、壁面处理和统计区间。DNS 不是菜单模型：无涡黏度并充分解析相关尺度的结论须另行验证。这些测试不是已验证的圆柱力统计或工业认证。可压缩、多相、任意流变求解流程不在本版范围内。')+'</div>'+
        '<h3>'+t('Initialisation, units and editable code','初值、单位与可编辑代码')+'</h3><pre>k = 1.5 (U I)^2                         [m2/s2]\nomega = sqrt(k) / (0.09^0.25 L)        [1/s]\nepsilon = 0.09^0.75 k^1.5 / L        [m2/s3]\nnuTilda = sa_viscosity_ratio * nu      [m2/s]\nR = diag(2k/3, 2k/3, 2k/3)            [m2/s2]\nv2 = 2k/3                             [m2/s2]\nf                                     [1/s]\nReThetat, gammaInt                     [dimensionless]\nflm, fmm (compatibility implementation) [m4/s4]</pre>'+
        '<p>'+t('I is an intensity fraction (0.01=1%); L is metres. Transition ReThetat defaults to 400 and gammaInt to 1 as editable seeds, not a case-specific transition correlation. SA viscosity ratio defaults to 3. Dynamic flm/fmm seed defaults to 0.01 m4/s4. Initial fields / dictionaries exposes all generated fields, R as volSymmTensorField, model coefficients and field solvers. Turbulence convection uses Gauss upwind; use research-appropriate schemes after verification. Switching models retains your overrides; stale model-field overrides are rejected before creating a case. An unchecked, explicit reset option removes only model-specific fields/numerics and preserves U,p/viscosity overrides.','I 为强度比例（0.01=1%），L 单位米。ReThetat 默认 400、gammaInt 默认 1，是可编辑初值，不是针对具体工况的转捩关联式。SA 黏度比默认 3；动态平均量默认 0.01 m4/s4。“初始场 / 字典”可编辑全部生成场、volSymmTensorField 类型 R、模型系数和各场线性求解器。湍流输运对流项使用 Gauss upwind，科研计算须验证后选择合适格式。切换模型保留手动覆盖，旧模型专属覆盖会在建算例前被拒绝。默认不勾选的明确重置选项仅清理模型专属场/数值覆盖，保留 U,p 和黏度覆盖。')+'</p>'+
        '<p>'+t('Standard k/epsilon wall-function presets use kqRWallFunction, epsilonWallFunction and nutkWallFunction; omega models use omegaWallFunction. SA/LES/hybrid use low-Re nut wall handling. Launder–Sharma uses k=0 and a positive epsilon wall regularisation max(epsilon_inlet×1e−8,1e−20) to avoid the actual 0/0 in its fMu calculation. This regularisation and all wall presets are explicitly reviewable in 0/*; near-wall resolution/y+ and physical boundary suitability remain problem-specific. v2f sets k,v2,f=0 on the wall. LES filter is cubeRootVol; DES/DDES uses maxDeltaxyz and IDDES uses IDDESDelta. SAS also needs delta cubeRootVol.','标准 k/epsilon 壁面函数预设使用 kqRWallFunction、epsilonWallFunction、nutkWallFunction；omega 模型使用 omegaWallFunction；SA、LES、混合模型采用低雷诺数 nut 壁面处理。Launder–Sharma 使用 k=0、epsilon 壁面正则化 max(epsilon入口×1e−8,1e−20)，避免 fMu 实际出现的 0/0。正则化与所有壁面预设均可在 0/* 核查；近壁分辨率、y+ 与物理边界适用性须按工况验证。v2f 壁面 k,v2,f=0。LES 滤波尺度用 cubeRootVol，DES/DDES 用 maxDeltaxyz，IDDES 用 IDDESDelta；SAS 也须配置 delta cubeRootVol。')+'</p>'+
        '<h3>'+t('Isolated dynamicLagrangian compatibility module','独立 dynamicLagrangian 兼容模块')+'</h3>'+
        '<p>'+t('The installed Foundation 14 constructor requires dimensionless flm/fmm, but its dimensional transport equations require velocity^4. Both failures were reproduced and retained. The GPL source module renames the runtime model to offDynamicLagrangian and corrects those two constructor dimension arguments; it preserves the original equations and dimension checking. It compiles with wmake into a version-specific user library. Installed /opt/OpenFOAM files are not modified. First use on another WSL/Slurm host requires Foundation 14 development headers, wmake and a C++ compiler. The case/SSH bundle includes source, Make files, COPYING and provenance; compilation errors appear in the case logs. The generated momentumTransport model name is therefore offDynamicLagrangian, while the GUI lists dynamicLagrangian with a compatibility explanation. Real remote Slurm execution remains untested.','本机 Foundation 14 构造器要求 flm/fmm 无量纲，后续有量纲输运方程却需要速度四次方；两种失败已实际复现并保存。GPL 源码兼容模块将运行时名称改为 offDynamicLagrangian，并仅修正两处构造器量纲参数，保留原方程与量纲检查。wmake 编译到版本独立的用户库，不修改 /opt 下的 OpenFOAM 文件。另一台 WSL/Slurm 主机首次使用须有 Foundation 14 开发头文件、wmake 和 C++ 编译器。算例及 SSH 包含源码、Make 文件、COPYING 和来源，编译错误保存在算例日志。因此生成 momentumTransport 中模型名为 offDynamicLagrangian，GUI 显示 dynamicLagrangian 并说明兼容实现。真实远程 Slurm 运行仍未验证。')+'</p><p>'+link('../native/dynamicLagrangian/PROVENANCE.json',t('Exact source modifications and provenance','具体源码修改与来源'))+' · '+link('../evidence/model_runtime_validation.json',t('All model case paths and actual results','全部模型算例路径与实测结果'))+' · '+link('../evidence/model_runtime_initial_attempt.json',t('Retained original failures','保留的首轮失败'))+'</p>'+
        '<p>'+link('https://doc.cfd.direct/openfoam/user-guide/turbulence',t('CFD Direct. (2026). OpenFOAM user guide: Turbulence modelling.','CFD Direct. (2026). OpenFOAM 用户指南：湍流建模。'))+' · '+link('https://github.com/OpenFOAM/OpenFOAM-14/tree/master/src/MomentumTransportModels/momentumTransportModels/LES/dynamicLagrangian','The OpenFOAM Foundation. (2026). dynamicLagrangian source (OpenFOAM 14).')+'</p>')
    cycles=json.loads((E/'optimization_cycles.json').read_text())
    cycle_zh=[
    ('工具外框增加视觉负担，仍需清楚执行状态。','紧凑线条图标、闲置无框、选中细下划线，保留对话框/后台状态。','真实鼠标、互斥工具、对话框与异步任务测试。'),
    ('固定小数位把微小色标范围舍入成零。','改用可保留科学计数法精度的范围输入。','真实输入 −1e−14 至 3e−14，核查 VTK 范围。'),
    ('只有 laminar 与 SST，缺少主流类型。','增加 24 个类型明确的模型选项及所需场说明。','逐项比对本机 Foundation 14 注册源码。'),
    ('仅添加模型名称无法提供缺失初始场与离散格式。','为各模型生成完整标量/张量、量纲、壁面和求解器字典。','全部 24 套字典结构及 R 类型检查。'),
    ('平铺模型缺少说明，二维可误提交 LES。','模型分类、用途和初始场提示，设置三维准入检查。','真实界面选择 WALE，拒绝二维 LES，保留二维 RAS。'),
    ('转捩/SA 初值被固定；NaN 可绕过正值检查。','初值可编辑，无关项禁用，拒绝非有限参数。','自定义转捩/SA 字段传播及七类 NaN 参数拒绝。'),
    ('CSV 忽略应力张量，失败导出会破坏旧文件。','张量分量、正确 Frobenius 模、原子 CSV 提交；VTK 导出全部模型场。','对称张量及成功/失败导出，保护原文件与原帧。'),
    ('真实求解暴露 SAS delta、低 Re 除零、动态模型量纲和误报。','补 delta，显式耗散正则化；独立 GPL 量纲兼容模块，保留量纲检查，修正误报。','24 个真实 5120 单元/4 核模型，4 步、3 帧、有限值和导出验证，保留失败日志。'),
    ('自动逐帧色标难以可靠比较，布局不可设置。','各场独立持久化配色、固定/自动范围、冻结范围、标题/刻度/字体/布局。','真实 11 帧保持范围，验证切场、保存、PNG/GIF 与非法设置拒绝。'),
    ('换模型可能带入旧 omega/k 覆盖；原生库仅本机可用。','提前拒绝旧场覆盖，提供明确可选重置；保留源码/许可证和目标主机编译流程。','真实模型切换、SSH 包/编译脚本及原功能完整回归。')]

    section('optimization-cycles',t('0.10 · Ten find–improve–retest cycles','0.10 · 十轮发现—改进—复测'),
        '<p>'+t('Ten documented cycles record a concrete observed deficiency, the implemented change, test evidence, timestamp and source hashes. Regression reruns do not invent extra cycles. Original failed model runs remain available, and release publication requires the current evidence to pass.','十轮记录逐一包含实际不足、实现改动、测试证据、时间戳和源码哈希。重复回归不虚构额外轮次。模型失败记录保留；发布须通过本版实测证据门槛。')+'</p>'+table([t('Cycle','轮次'),t('Observed deficiency','实际发现'),t('Improvement','改进'),t('Retest','复测')],[[r['cycle'],html.escape(cycle_zh[r['cycle']-1][0] if zh else r['problem']),html.escape(cycle_zh[r['cycle']-1][1] if zh else r['improvement']),html.escape(cycle_zh[r['cycle']-1][2] if zh else r['test'])+' · PASS'] for r in cycles])+ '<p>'+link('../evidence/optimization_cycles.json',t('Complete timestamp/hash/evidence ledger','完整时间戳、哈希与证据记录'))+' · '+link('../evidence/final_regression_validation.json',t('Additive full-workflow regression results','保留原功能的全流程回归结果'))+'</p>')
    from off.advisor import SOURCES
    expert_rows=json.loads((E/'five_cycle_review.json').read_text(encoding='utf-8'))['cycles']
    section('expert-reynolds',t('0.11 · Expert mode and Reynolds scaling','0.11 · 专家模式与雷诺数联动'),
        '<p>'+t('Use the top-right Workflow selector: Expert opens direct access through Expert tools; Guided opens the optional workflow dock. Neither mode removes drafting, dictionaries, terminal, queue, SSH or result tools. The active mode remains visible on every workspace.','顶部右侧“工作方式”可选专家或引导模式。专家工具直接访问模型、网格、初始场、代码、终端与 SSH；引导模式显示可选流程面板。两种模式均保留绘图、字典、终端、队列、SSH 和结果工具，各工作区均可看到当前模式。')+'</p>'+pic('expert_advisor_workbench.png',t('Actual native workbench: visible mode, Expert tools, Reynolds and Setup advice','实际原生界面：可见模式、专家工具、雷诺数及设置建议'))+
        '<p>'+t('Click Reynolds. Re=UL/nu uses SI metres, m/s and m²/s. Enter 1≤target Re≤10⁷, then click Calculate nu to preserve U and L, or Calculate U to preserve nu and L. The target input alone never changes physics. Current Re and the resulting SI values are displayed before OK. Cancel leaves the project unchanged.','点击“雷诺数”。Re=UL/nu 使用 SI 米、m/s、m²/s。输入 1≤目标 Re≤10⁷ 后，点“计算 nu”保持 U、L，或点“计算 U”保持 nu、L。仅输入目标不会改变物理参数。确定前显示实际 Re 与对应 SI 参数；取消不更改项目。')+'</p>'+pic('reynolds_dialog.png',t('SI scale controls, geometric/custom L, common Re targets and explicit solve actions','SI 参数、几何/自定义 L、常用 Re 与明确计算动作'))+
        '<p>'+t('Automatic L follows the sole obstacle width (diameter for a circular cylinder). Multiple obstacles or an empty domain require an explicit custom L. Custom L is a coefficient/scaling reference, not a drawing dimension: geometry never changes. OpenFOAM force lRef and FFT St_L use the same L; drag/lift Aref remains projected obstacle width × extrusion depth. Existing U/viscosity overrides are shown and must be reviewed or explicitly reset; other dictionary overrides remain intact.','自动 L 跟随唯一实体宽度（圆柱为直径）。多实体或空流场需明确指定自定义 L。自定义 L 是系数/无量纲参考，不是几何尺寸，不会缩放实体。OpenFOAM 力系数 lRef 与 FFT 的 St_L 使用同一 L；阻力/升力 Aref 仍为实体投影宽度×拉伸深度。已有 U/黏度覆盖须核对或明确重置；其他字典覆盖保留。')+'</p>')
    section('setup-advice',t('0.11 · Recommendations grounded in the current mesh','0.11 · 基于当前真实网格的建议'),
        '<p>'+t('Setup advice offers two goals: engineering mean/URANS comparison, or resolving 3D wake fluctuations. The recommendation is a transparent starting heuristic, not a universal Reynolds-number threshold for turbulence. For the circular-cylinder screening, Re_D<300 offers laminar; above that engineering comparison offers SST, while a resolved-wake goal offers WALE only with 3D eligibility. These 300/10⁵ bands are application heuristics, not claimed physical transition boundaries. Geometry, inlet turbulence, roughness, wall treatment, uncertainty and benchmark evidence still govern the decision.','“设置建议”区分工程均值/URANS 对比与解析三维尾流波动。推荐是公开的起始启发规则，并非通用湍流雷诺数阈值。圆柱筛查中 Re_D<300 提供层流起点；更高 Re 的工程对比提供 SST，解析尾流目标仅在三维准入时提供 WALE。这些 300/10⁵ 区间是应用启发规则，不声称为真实转捩边界。仍须依据几何、入口湍流、粗糙度、壁面处理、不确定性和基准数据作决定。')+'</p>'+pic('setup_advice.png',t('Actual mesh evidence and gated explicit model application','实际网格证据及受控的明确模型应用'))+
        '<p>'+t('Only completed local cases with matching geometry, mesh controls and actual off_project.json metadata can supply mesh evidence. The report recalculates OpenFOAM-style quality, worst faces, cell count and cylinder wall-normal cell-centre distances. Cache reuse requires the SHA-256 of points/faces/owner/neighbour/boundary and matching quality thresholds. A geometry/mesh change invalidates older matching cases. External mesh edits are not geometrically certified merely by metadata; structured cell-count mismatch blocks application.','仅几何、网格控制与真实 off_project.json 元数据匹配的本地完成算例可提供网格证据。报告重新计算 OpenFOAM 风格质量、最坏面、网格数及圆柱壁面首层中心法向距离。缓存须同时匹配 points/faces/owner/neighbour/boundary 的 SHA-256 与质量阈值；几何/网格修改会使旧算例失配。仅凭元数据不认证外部网格编辑；结构网格数不符会阻止应用。')+'</p>'+
        '<p>'+t('Measured first-cell distance is geometric, not y+. y+ stays unknown until measured from a solved case. Re alone never infers y+. LES/DES also needs resolved energy, wall/wake/filter scales, suitable span boundaries and statistical convergence; default front/back symmetryPlane is not a periodic LES span. High-Re cylinder drag crisis/transition depends on roughness and inlet turbulence. When a physical sound speed is supplied, Ma=U/a≥0.3 blocks the incompressible recommendation; without it Mach is explicitly unknown.','首层法向距离是几何测量，不是 y+；未从求解算例实测时 y+ 明确为未知。不能从 Re 推断 y+。LES/DES 还需解析能量、近壁/尾流/滤波尺度、适合的展向边界及统计收敛；默认前后 symmetryPlane 并非周期 LES 展向。高 Re 圆柱阻力危机/转捩取决于粗糙度及入口湍流。提供实际声速后，Ma=U/a≥0.3 会阻止不可压缩推荐；否则 Ma 明确为未知。')+'</p>'+
        '<pre>G = max_cells [ Σ_faces |(1,0,0) · S_f| / (2 V) ]\nCo_uniform = Δt · U · G\nΔt_start_estimate = Co_limit / (U · G)</pre><p>'+t('G comes from genuine face area vectors and cell volumes. This uniform-inlet geometric estimate excludes acceleration/crossflow and never replaces actual solver maximum Co or time-step convergence. No automatic change to dt, end time or mesh is made. Application is disabled without matching mesh evidence, for invalid/excessive quality, non-finite metrics, high Mach or dictionary overrides. Review checkbox + Apply changes the model only.','G 来自真实面面积矢量与体积。均匀入口几何估算不含加速/横向流动，不替代实际最大 Co 或时间步收敛。不会自动改变 dt、结束时间或网格。无匹配实测网格、质量非法/超限、指标非有限、高 Ma 或存在字典覆盖时不能应用；勾选核验并点击应用只更改模型。')+'</p>'+''.join('<p>'+link(r['url'],html.escape(r['label']))+'</p>' for r in SOURCES))
    section('five-cycle-qa',t('0.11 · Five test-engineer review and correction stages','0.11 · 五轮测试工程师复核与修正'),
        table([t('Round','轮次'),t('Deficiency found','发现不足'),t('Correction and verification','修正与验证')],[[r['cycle'],html.escape(r['problem_zh'] if zh else r['problem']),html.escape(r['improvement_zh'] if zh else r['improvement'])+' · '+r['result']] for r in expert_rows])+ '<p>'+link('../evidence/five_cycle_review.json',t('Five-stage evidence ledger','五轮证据记录'))+' · '+link('../evidence/advisor_integration.json',t('Actual mesh recommendation integration','真实网格建议集成验证'))+' · '+link('../evidence/model_runtime_validation.json',t('24 retained 0.11 MPI model tests','保留的 0.11 版 24 个 MPI 模型测试'))+'</p><p>'+t('The original 0.10 ten-cycle ledger is retained as historical evidence. The 0.11 release added the five review stages and 24 model tests, retained here as historical evidence. Historical 0.12 added three fresh 3D pipelines, eight fresh 10-second pipelines, current drafting/file tests and preserved-workflow regressions. These are software integration checks, not a Re=10⁷ production-accuracy certificate. Failed first attempts are retained.','原 0.10 十轮记录作为历史证据保留。0.11 新增的五轮复核和 24 个模型测试在此作为历史证据保留。历史 0.12 新增三轮三维全流程、八轮 10 秒全流程、绘图/文件测试和原流程回归。这些为软件集成验证，不是 Re=10⁷ 正式计算精度认证，首次失败记录保留。')+'</p>')
    long_qa=json.loads((E/'eight_long_runs/ledger.json').read_text(encoding='utf-8'))
    assert long_qa.get('eight_rounds_passed') and len(long_qa['rounds'])==8
    section('eight-long-runs',t('0.12 · Eight retained 0.12 full 10-second QA simulations','0.12 · 保留的 0.12 八轮完整 10 秒测试'),
        '<p>'+t('Eight additional sequential rounds each integrate the real three-dimensional incompressible equations from 0 to 10 s on 5120 cells with four MPI ranks. Saved fields are genuine 0, 0.5, …, 10 s frames; every required model field is checked for finite values at all 21 frames. Mesh checks, force output, CSV, PINN MAT, PNG and real-frame GIF are verified. Round 3 also verifies an actual STOP/CONT pause and continuation.','额外八轮按顺序完成真实三维不可压缩方程 0–10 s 求解，每轮 5120 单元、4 个 MPI 进程。保存场为真实 0、0.5、…、10 s 共 21 帧；每一帧所有模型必需场均检查有限值。核验网格、力数据、CSV、PINN MAT、PNG 与真实帧 GIF；第三轮还实测 STOP/CONT 暂停与续算。')+'</p>'+table([t('Round','轮次'),'Re',t('Model','模型'),'t / s',t('Cells / ranks','单元 / 进程'),'max Co',t('Frames','帧'),t('Result','结果')],[[r['round'],r['Re'],r['model'],r['end_time_s'],str(r['cells'])+' / '+str(r['cores']),f'{r["max_observed_Co"]:.6g}',r['genuine_frames'],r['result']] for r in long_qa['rounds']])+ '<p>'+link('../evidence/eight_long_runs/ledger.json',t('Complete eight-round results and retained failures','完整八轮结果与失败记录'))+'</p><p>'+t('The laminar dt variation is an integration regression, not demonstrated time-step convergence. The 10 s observation time may contain too few shedding periods for a converged St. Coarse WALE/DES/native-SGS runs validate software contracts and finite-field execution; neither cell count nor elapsed simulation time certifies turbulent physics.','层流时间步变化为集成回归，不声称已证明时间步收敛。10 s 观察可能不足以获取收敛 St。粗网格 WALE/DES/原生 SGS 测试验证软件接口与场值有限执行，不以网格数或时长认证湍流物理精度。')+'</p>')
    section('drawing-files',t('0.12 · Design, meshing and every generated file','0.12 · 设计、网格与全部生成文件'),
        '<p>'+t('Preprocess has compact Design and Meshing subtabs. Geometry contains solid shapes only; the single Mesh operations tree owns refinement/spacing controls. A region is a size-control input, not an already generated grid. Double-click Mesh operations routes to Meshing, not Results.','前处理有紧凑的设计/网格子选项卡。几何分支只管理实体；唯一网格操作分支管理加密/间距控制。区域是尺寸控制输入，不是已生成单元。双击网格操作会进入网格子页，不再误跳结果。')+'</p>'+pic('meshing_workspace_'+lang+'.png',t('Actual native meshing workspace','真实原生网格界面'))+
        '<p>'+t('Polygon solid: click vertices and press Enter/right click to close. It is a genuine Gmsh cut/extruded solid; open Line/Polyline stays construction-only. Circle, rectangle and triangle support two clicks as well as legacy drag drawing. Esc cancels; self-intersections are rejected. Incompatible default O-grid switches to Gmsh unless a manual block override must first be reviewed; geometry Undo restores the earlier method.','多边形实体：逐点点击，以 Enter/右键闭合，实际参与 Gmsh 切割/拉伸。开放直线/折线仍为辅助线。圆、矩形、三角形支持两次点击，也保留拖绘；Esc 取消，拒绝自交。不兼容的默认 O-grid 改用 Gmsh；已有手动块覆盖时须先核对。几何撤销同时恢复原方法。')+'</p>'+
        table([t('Backend','生成器'),t('Methods','方式'),t('Actual inputs','真实输入')],[['blockMesh','Structured cylinder O-grid / partitioned box','system/blockMeshDict → constant/polyMesh'],['Gmsh → gmshToFoam','Triangle/prism; quad-dominant/prism; tetrahedral','geometry.msh / geometry.brep; mesh_generator_source.py → constant/polyMesh']])+
        '<p>'+t('Files menu is available on every workspace. Generated design files builds actual drafts with 0/U,p and model fields, all system/constant dictionaries, mesh input and source snapshot. The OpenFOAM run-directory browser also exposes all older cases without a queue selection. Selected case shows all actual polyMesh, saved fields and logs read-only; Application source shows every software source file. Draft blockMeshDict edits can be saved as explicit project overrides and actually used by blockMesh. Program source/actual cases are protected in this browser; the existing inactive-case dictionary editor remains available.','文件菜单在全部工作区可见。生成设计文件产生真实草稿：0/U、p 与模型场、system/constant 字典、网格输入与源码快照。OpenFOAM 算例目录入口无需队列选择即可查看旧算例。所选算例只读展示实际 polyMesh、时间场、日志；软件源码展示全部源码。草稿 blockMeshDict 可编辑保存为项目覆盖，实际由 blockMesh 使用。本浏览器保护源码/实际算例；原有非活动算例字典编辑器仍保留。')+'</p>'+pic('generated_file_browser.png',t('Actual dictionary/source file browser','真实字典/源码浏览器'))+
        '<p>'+t('Draft inputs are not a checked mesh or solved result. Gmsh BREP is geometry, not a mesh; MSH is the generated mesh. Quad-dominant recombination does not promise all quads. Manual planar multiblock topology is implemented in 0.14; general 3D CAD booleans are not implemented. 3D drawing remains planar extrusion. Manual block code can express custom topology but still must pass checkMesh.','草稿输入不等于已检查网格或求解结果。Gmsh BREP 是几何，MSH 才是生成网格。四边形主导重组不保证全四边形。0.14 新增手动平面多块拓扑；尚未实现通用三维 CAD 布尔，三维绘制仍为平面拉伸。手动块代码可表达自定义拓扑，但仍须通过 checkMesh。')+'</p><p>'+link('../evidence/drawing_files_validation.json',t('Actual mouse/manual-block/polygon QA evidence','真实鼠标/手动块/多边形验证证据'))+' · '+link('quickstart_'+lang+'.html',t('Seven quick tutorials and seven starters','七个快速教程及七个模板'))+'</p>')
    polygon_run=json.loads((E/'polygon_pipeline_validation.json').read_text())
    section('polygon-proof',t('0.12 · Actual custom-polygon solve','0.12 · 自定义多边形真实求解'),
        '<p>'+t('A pentagonal obstacle drawn as a planar solid was actually extruded and meshed with Gmsh, converted with gmshToFoam, solved with four MPI ranks and exported as genuine CSV/MAT/PNG/GIF. This short run verifies new geometry integration; it does not qualify wake statistics.','五边形平面实体实际拉伸，由 Gmsh 划分，经 gmshToFoam 转换，以四个 MPI 进程求解并导出真实 CSV/MAT/PNG/GIF。这一短算例核验新几何流程，不认证尾流统计。')+'</p>'+table([t('Quantity','指标'),t('Actual result','实际结果')],[['Cells',polygon_run['cells']],['Ranks',polygon_run['cores']],['Simulated time / s',polygon_run['end_time_s']],['Genuine saved frames',polygon_run['genuine_frames']],['Max skewness',polygon_run['quality']['skewness']],['Max non-orthogonality / °',polygon_run['quality']['non_orthogonality']],['Max observed Co',polygon_run['max_observed_Co']]])+pic('polygon_pipeline/mesh.png',t('Actual converted 3D polygon mesh, captured directly from VTK','实际转换后的三维多边形网格，直接捕获 VTK'))+'<p>'+link('../evidence/polygon_pipeline_validation.json',t('Full measured polygon evidence','多边形完整实测证据'))+' · '+link('../evidence/input_access_validation.json',t('Actual input save/rebuild and bilingual UI tests','真实输入保存/重建与双语界面测试'))+'</p>')
    title=t('User guide & verified release evidence','使用说明与实测验证报告')
    other='ZH' if lang=='EN' else 'EN'
    nav=''.join(f'<a href="#{i}">{label}</a>' for i,label in [('drawing-files',t('Design / files','设计 / 文件')),('eight-long-runs',t('8 × 10s QA','八轮 10s 测试')),('expert-reynolds',t('Expert / Re','专家 / Re')),('setup-advice',t('Setup advice','设置建议')),('five-cycle-qa',t('Prior 0.11 QA','历史 0.11 复核')),('workbench',t('Workflow','引导流程')),('install',t('Install','安装')),('sketch',t('Sketch','绘图')),('mesh',t('Mesh','网格')),('quality',t('Quality','质量')),('queue',t('Queue','队列')),('colourmap',t('Colour map','色标')),('physics-models',t('Models','模型')),('optimization-cycles',t('10 cycles','十轮改进')),('post',t('Export','导出')),('verification',t('Validation','验证'))])
    document=f'<!doctype html><html lang="{"zh-CN" if zh else "en"}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Open Foam Friend — {title}</title><style>{css}</style><header><h1>Open Foam Friend</h1><p>{title} · {BASE.name} · Engineering 0.16.0<br>Authors: zongxuan and hanwen · Qt / Gmsh / VTK / OpenFOAM Foundation 14</p><a href="manual_{other}.html">{"English version" if zh else "中文版"}</a></header><nav>{nav}</nav><main>'+''.join(parts)+'</main><footer>Open Foam Friend · zongxuan and hanwen · Evidence-based engineering release</footer></html>'
    (DOC/f'manual_{lang}.html').write_text(document,encoding='utf-8')

manifest={'release':BASE.name,'version':'0.16.0','authors':['zongxuan','hanwen'],'validation':V,'sha256':{}}
manifest['evidence_scope']=json.loads((E/'current_release_scope.json').read_text())
for filename in ('upgrade_validation.json','additional_validation.json','checkpoint_validation.json','workbench_validation.json','professional.json','shortcuts.json','hci_validation.json','navigation_validation.json','docking_ssh_validation.json','selection_dimensions_validation.json','twoD_pipeline_validation.json','workspace_upgrade_validation.json','button_feedback_validation.json'):
    if (E/filename).exists(): manifest[filename.removesuffix('.json')]=json.loads((E/filename).read_text())
for folder in ('off','tests','tools','docs','native'):
    for p in sorted((BASE/folder).rglob('*')):
        if p.is_file() and '__pycache__' not in str(p): manifest['sha256'][p.relative_to(BASE).as_posix()]=hashlib.sha256(p.read_bytes()).hexdigest()
for name in ('app.py','requirements.txt','launch.cmd','install.ps1','README.md'):
    manifest['sha256'][name]=hashlib.sha256((BASE/name).read_bytes()).hexdigest()
for p in E.rglob('*.json'):
    manifest['sha256'][p.relative_to(BASE).as_posix()]=hashlib.sha256(p.read_bytes()).hexdigest()
(BASE/'release_manifest.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
print('Wrote bilingual manuals and source/evidence manifest:',BASE)

